#!/usr/bin/env bun
import { existsSync, rmSync } from "node:fs"
import { join, resolve } from "node:path"

import { buildMockup, summary, type BuildOutcome, type Scheme } from "./build"
import { DEFAULT_MAX_PROBLEMS, formatProblems } from "./checks"
import { galleryHeadline, galleryJson, galleryLines, screenshotSummary, writeGallery } from "./gallery"
import { componentDetail, detailJson, detailText, indexJson, indexText } from "./inspect"
import { displayPath, EnvironmentError, findProject, mockupDirectory, type MockupProject } from "./project"
import { registryListJson, registryListText } from "./registry"
import { sdkDetail, sdkDetailJson, sdkDetailText, sdkIndexJson, sdkIndexText } from "./sdk"
import { readStates, selectStates } from "./states"
import { outFor, partsSummary, validateMockup } from "./validate"
import { version } from "./version"

const COMMANDS = new Set(["inspect", "build", "validate", "gallery", "clean"])
const VALUE_FLAGS = new Set([
  "--project",
  "--css",
  "--tsconfig",
  "--tailwind",
  "--theme",
  "--scheme",
  "--out",
  "--max",
  "--state",
])

const USAGE = `eskais-mockup ${version}: offline HTML mockups of a project's own components

  bun .agents/tools/eskais-mockup/cli.ts inspect [Names…] [--registry | --sdk] [--json]
  bun .agents/tools/eskais-mockup/cli.ts build <name> [--state <name>|all] [--theme <name>] [--scheme light|dark|system] [--out <file>] [--gallery]
  bun .agents/tools/eskais-mockup/cli.ts validate <name> [--state <name>|all] [--gallery]
  bun .agents/tools/eskais-mockup/cli.ts gallery [dir] [--json]
  bun .agents/tools/eskais-mockup/cli.ts clean [name]
  bun .agents/tools/eskais-mockup/cli.ts --version

Every command takes --project <dir>, --css <file> (the stylesheet), --tsconfig <file> and --tailwind <dir>
(a folder whose packages resolve Tailwind, in a workspace where only an app installs it).
inspect lists the project's components; --registry lists the registry items it has not installed,
--sdk the @ui-sdk subpaths it installs, and --sdk <name> one primitive's parts and props.
A mockup lives in <project>/.mockups/<name>/ with screen.tsx, fixtures.ts, parts/ and an optional
../wrapper.tsx. fixtures.ts may export states = { empty: {…}, error: {…} }, the screen's props in each named
state: --state <name> builds out-<name>-<theme>.html, --state all one page per state. Build each state and theme as out-<state>-<theme>.html, capture each as a PNG with the
same name, and gallery writes <dir>/gallery.html (default .mockups) with every screenshot. Exit codes: 0 ok, 1 problems to fix, 2 environment or usage error.`

type Options = {
  command: "inspect" | "build" | "validate" | "gallery" | "clean"
  names: string[]
  json: boolean
  gallery: boolean
  registry: boolean
  sdk: boolean
  max: number
  scheme: Scheme
  project?: string | undefined
  css?: string | undefined
  tsconfig?: string | undefined
  tailwind?: string | undefined
  theme?: string | undefined
  out?: string | undefined
  state?: string | undefined
}

function parseArgs(argv: string[]): Options | "help" | "version" {
  const [command, ...rest] = argv
  if (command === undefined || command === "help" || command === "--help" || command === "-h") return "help"
  if (command === "version" || command === "--version" || command === "-v") return "version"
  if (!COMMANDS.has(command)) {
    throw new EnvironmentError(`unknown command "${command}"; use inspect, build, validate, gallery or clean`)
  }
  const options: Options = {
    command: command as Options["command"],
    names: [],
    json: false,
    gallery: false,
    registry: false,
    sdk: false,
    max: DEFAULT_MAX_PROBLEMS,
    scheme: "system",
  }
  for (let index = 0; index < rest.length; index += 1) {
    const argument = rest[index] ?? ""
    const separator = argument.indexOf("=")
    const flag = separator === -1 ? argument : argument.slice(0, separator)
    const inline = separator === -1 ? undefined : argument.slice(separator + 1)
    if (flag === "--json") {
      options.json = true
      continue
    }
    if (flag === "--gallery") {
      options.gallery = true
      continue
    }
    if (flag === "--registry" || flag === "--sdk") {
      options[flag === "--registry" ? "registry" : "sdk"] = true
      if (inline !== undefined) options.names.push(inline)
      continue
    }
    if (flag === "--help" || flag === "-h") return "help"
    if (flag === "--version") return "version"
    if (VALUE_FLAGS.has(flag)) {
      const value = inline ?? rest[index + 1]
      if (value === undefined) throw new EnvironmentError(`${flag} needs a value`)
      if (inline === undefined) index += 1
      applyValue(options, flag, value)
      continue
    }
    if (flag.startsWith("-")) throw new EnvironmentError(`unknown option "${flag}"`)
    options.names.push(argument)
  }
  return options
}

function applyValue(options: Options, flag: string, value: string) {
  if (flag === "--max") {
    const max = Number(value)
    if (!Number.isInteger(max) || max < 1) throw new EnvironmentError(`--max needs a positive whole number`)
    options.max = max
    return
  }
  if (flag === "--scheme") {
    if (value !== "light" && value !== "dark" && value !== "system") {
      throw new EnvironmentError(`--scheme must be light, dark or system`)
    }
    options.scheme = value
    return
  }
  if (flag === "--state" && !/^[\w-]+$/.test(value)) throw new EnvironmentError(`"${value}" is not a state name`)
  if (flag === "--project") options.project = value
  if (flag === "--css") options.css = value
  if (flag === "--tsconfig") options.tsconfig = value
  if (flag === "--tailwind") options.tailwind = value
  if (flag === "--state") options.state = value
  if (flag === "--theme") options.theme = value
  if (flag === "--out") options.out = value
}

function mockupName(options: Options): string {
  const name = options.names[0]
  if (name === undefined) throw new EnvironmentError(`${options.command} needs a mockup name`)
  if (!/^[\w.-]+$/.test(name)) throw new EnvironmentError(`"${name}" is not a mockup name`)
  return name
}

function runGallery(options: Options, cwd: string): number {
  if (options.names.length > 1) throw new EnvironmentError("gallery takes one folder")
  const named = options.names[0]
  const dir =
    named === undefined ? join(findProject(projectOptions(options, cwd)).root, ".mockups") : resolve(cwd, named)
  const outcome = writeGallery(dir)
  if (options.json) console.log(JSON.stringify(galleryJson(outcome, cwd), null, 2))
  else for (const line of galleryLines(outcome, cwd)) console.log(line)
  return outcome.path === null ? 1 : 0
}

function printGallery(project: MockupProject, cwd: string) {
  const outcome = writeGallery(join(project.root, ".mockups"))
  console.log(galleryHeadline(outcome, cwd))
}

function projectOptions(options: Options, cwd: string) {
  return { cwd, project: options.project, css: options.css, tsconfig: options.tsconfig, tailwind: options.tailwind }
}

function statesLine(mockup: string): string[] {
  try {
    const states = readStates(mockup)
    return states === null || states.length === 0 ? [] : [`states ${states.length}: ${states.join(", ")}`]
  } catch {
    return []
  }
}

async function run(options: Options, cwd: string): Promise<number> {
  if (options.gallery && options.command !== "build" && options.command !== "validate") {
    throw new EnvironmentError("--gallery works with build and validate; use the gallery command")
  }
  if (options.state !== undefined && options.command !== "build" && options.command !== "validate") {
    throw new EnvironmentError("--state works with build and validate")
  }
  if (options.command === "gallery") return runGallery(options, cwd)
  const project = findProject(projectOptions(options, cwd))
  if (options.command === "inspect") {
    if (options.registry && options.sdk) {
      throw new EnvironmentError("inspect takes --registry or --sdk, not both")
    }
    if (options.registry) {
      if (options.names.length > 0) throw new EnvironmentError("inspect --registry takes no names")
      console.log(
        options.json
          ? JSON.stringify(await registryListJson(project, cwd), null, 2)
          : await registryListText(project, cwd),
      )
      return 0
    }
    if (options.sdk) {
      if (options.names.length === 0) {
        console.log(options.json ? JSON.stringify(sdkIndexJson(project), null, 2) : sdkIndexText(project, cwd))
        return 0
      }
      const details = options.names.map((name) => sdkDetail(project, name))
      console.log(
        options.json
          ? JSON.stringify(
              details.map((detail) => sdkDetailJson(detail, cwd)),
              null,
              2,
            )
          : details.map((detail) => sdkDetailText(detail, cwd)).join("\n\n"),
      )
      return 0
    }
    if (options.names.length === 0) {
      console.log(options.json ? JSON.stringify(indexJson(project, cwd), null, 2) : indexText(project, cwd))
      return 0
    }
    const details = options.names.map((name) => componentDetail(project, name))
    console.log(
      options.json
        ? JSON.stringify(
            details.map((detail) => detailJson(detail, cwd)),
            null,
            2,
          )
        : details.map((detail) => detailText(detail, cwd)).join("\n\n"),
    )
    return 0
  }
  if (options.command === "clean") {
    const target =
      options.names.length === 0 ? join(project.root, ".mockups") : mockupDirectory(project, options.names[0] ?? "")
    const shown = displayPath(target, cwd)
    if (!existsSync(target)) {
      console.log(`nothing to clean: ${shown} does not exist`)
      return 0
    }
    rmSync(target, { recursive: true, force: true })
    console.log(`removed ${shown}`)
    return 0
  }
  const settings = {
    name: mockupName(options),
    scheme: options.scheme,
    cwd,
    theme: options.theme,
    out: options.out,
  }
  const mockup = mockupDirectory(project, settings.name)
  if (!existsSync(join(mockup, "screen.tsx"))) {
    throw new EnvironmentError(
      `no mockup named ${settings.name}: ${displayPath(join(mockup, "screen.tsx"), cwd)} does not exist`,
    )
  }
  const states = selectStates(mockup, options.state)
  if (options.command === "build") {
    const outcomes: BuildOutcome[] = []
    for (const state of states) {
      // oxlint-disable-next-line no-await-in-loop -- each build writes the same entry file and registry cache
      outcomes.push(await buildMockup(project, { ...settings, state, out: outFor(options.out, state, states) }))
    }
    for (const warning of outcomes.flatMap((outcome) => outcome.warnings)) console.error(`warning: ${warning}`)
    const problems = outcomes.flatMap((outcome) => outcome.problems)
    if (problems.length > 0) {
      for (const line of formatProblems(problems, options.max)) console.log(line)
      return 1
    }
    for (const outcome of outcomes) console.log(summary(outcome, cwd))
    if (options.gallery) printGallery(project, cwd)
    return 0
  }
  const outcome = await validateMockup(project, settings, states)
  for (const warning of outcome.warnings) console.error(`warning: ${warning}`)
  const summaryLines = [...partsSummary(outcome.build.manifest), ...statesLine(mockup), screenshotSummary(mockup)]
  if (outcome.problems.length > 0) {
    for (const line of formatProblems(outcome.problems, options.max)) console.log(line)
    for (const line of summaryLines) console.log(line)
    return 1
  }
  for (const built of outcome.builds) console.log(`ok ${summary(built, cwd)}`)
  for (const line of summaryLines) console.log(line)
  if (options.gallery) printGallery(project, cwd)
  return 0
}

try {
  process.on("unhandledRejection", (reason) => {
    const message = reason instanceof Error ? reason.message : String(reason)
    console.error(`warning: the mockup left a promise rejected (${message})`)
  })
  const options = parseArgs(process.argv.slice(2))
  if (options === "help") console.log(USAGE)
  else if (options === "version") console.log(`eskais-mockup ${version}`)
  else process.exitCode = await run(options, process.cwd())
} catch (error) {
  if (!(error instanceof EnvironmentError)) throw error
  console.error(error.message)
  process.exitCode = 2
}

import { createHash } from "node:crypto"
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { basename, dirname, extname, join, relative, resolve } from "node:path"
import { createRequire } from "node:module"
import { pathToFileURL, fileURLToPath } from "node:url"

import { pageProblems, reactDevBanner, viewportProblems, type Problem } from "./checks"
import { matchMap, STYLE_CONDITIONS } from "./package-map"
import { readMockupParts, type Gap, type MockupParts, type ProposedPart, type SdkPart } from "./parts"
import {
  displayPath,
  EnvironmentError,
  locatePackage,
  mockupDirectory,
  specifierOf,
  type MockupProject,
} from "./project"
import { prepareRegistry, type InstallEntry } from "./registry"
import { stateOutName } from "./states"

export type Scheme = "light" | "dark" | "system"

export type BuildSettings = {
  name: string
  scheme: Scheme
  cwd: string
  theme?: string | undefined
  out?: string | undefined
  state?: string | undefined
}

export type BuildOutcome = {
  outPath: string
  manifestPath: string
  total: number
  js: number
  css: number
  fonts: number
  problems: Problem[]
  warnings: string[]
  manifest: MockupManifest
  parts: MockupParts
}

export type MockupManifest = {
  name: string
  date: string
  theme: string | null
  scheme: Scheme
  state: string | null
  hashes: { screen: string | null; fixtures: string | null }
  components: string[]
  install: InstallEntry[]
  proposed: ProposedPart[]
  sdkParts: SdkPart[]
  gaps: Gap[]
  size: { total: number; js: number; css: number; fonts: number }
}

type Resolver = (id: string, base: string) => Promise<string | undefined>

type CompileOptions = {
  base: string
  from: string
  onDependency: (path: string) => void
  shouldRewriteUrls: boolean
  customCssResolver: Resolver
  customJsResolver: Resolver
}

type TailwindCompiler = {
  build(candidates: string[]): string
}

type TailwindModule = {
  compile(css: string, options: CompileOptions): Promise<TailwindCompiler>
  Scanner: new (options: { sources: { base: string; pattern: string; negated: boolean }[] }) => { scan(): string[] }
}

const SIZE_WARNING = 3 * 1024 * 1024

const DATA_URL_TYPES: Record<string, string> = {
  ".avif": "image/avif",
  ".gif": "image/gif",
  ".ico": "image/x-icon",
  ".jpeg": "image/jpeg",
  ".jpg": "image/jpeg",
  ".otf": "font/otf",
  ".png": "image/png",
  ".svg": "image/svg+xml",
  ".ttf": "font/ttf",
  ".webp": "image/webp",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
}

const FONT_EXTENSIONS = new Set([".woff", ".woff2", ".ttf", ".otf"])

export function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} kB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

async function loadTailwind(project: MockupProject): Promise<TailwindModule> {
  const node = (await import(pathToFileURL(project.runtime.tailwindNode).href)) as {
    compile: TailwindModule["compile"]
  }
  const oxide = (await import(pathToFileURL(project.runtime.tailwindOxide).href)) as {
    Scanner: TailwindModule["Scanner"]
  }
  return { compile: node.compile, Scanner: oxide.Scanner }
}

function inlineAssets(css: string, base: string): { css: string; fonts: number } {
  let fonts = 0
  const inlined = css.replaceAll(/url\(\s*(["']?)([^)"']+)\1\s*\)/g, (match: string, _quote: string, href: string) => {
    if (href.startsWith("data:") || href.startsWith("#")) return match
    const file = resolve(base, href)
    if (!existsSync(file)) return match
    const bytes = readFileSync(file)
    const extension = extname(file).toLowerCase()
    if (FONT_EXTENSIONS.has(extension)) fonts += bytes.length
    const type = DATA_URL_TYPES[extension] ?? "application/octet-stream"
    return `url("data:${type};base64,${bytes.toString("base64")}")`
  })
  return { css: inlined, fonts }
}

export function bareName(id: string): string | null {
  if (/^[./#\\]/.test(id) || id.includes(":")) return null
  const parts = id.split("/")
  if (!id.startsWith("@")) return parts[0] === "" ? null : (parts[0] ?? null)
  return parts.length > 1 && parts[1] !== "" ? `${parts[0] ?? ""}/${parts[1] ?? ""}` : null
}

function installedAbove(base: string, name: string): boolean {
  let current = resolve(base)
  for (;;) {
    if (existsSync(join(current, "node_modules", name))) return true
    const parent = dirname(current)
    if (parent === current) return false
    current = parent
  }
}

function isFile(path: string): boolean {
  return existsSync(path) && statSync(path).isFile()
}

function exportsMap(exported: unknown): unknown {
  const keyed =
    typeof exported === "object" &&
    exported !== null &&
    !Array.isArray(exported) &&
    Object.keys(exported).some((key) => key.startsWith("."))
  return keyed ? exported : { ".": exported }
}

// A stylesheet the project's stylesheet imports from a package its own folder doesn't install, as in a workspace
// where only an app depends on tailwindcss: found in the workspace, through the package's style export.
export function workspaceStylesheet(project: MockupProject, id: string, base: string): string | undefined {
  const name = bareName(id)
  if (name === null || installedAbove(base, name)) return undefined
  const dir =
    (name === "tailwindcss" ? project.runtime.tailwindPackage : null) ??
    locatePackage(project.resolution, name)?.dir ??
    null
  if (dir === null) return undefined
  const packageJson = JSON.parse(readFileSync(join(dir, "package.json"), "utf8")) as {
    exports?: unknown
    style?: unknown
  }
  const subpath = `.${id.slice(name.length)}`
  const exported = matchMap(exportsMap(packageJson.exports), subpath, STYLE_CONDITIONS)
  const style = typeof packageJson.style === "string" ? packageJson.style : "index.css"
  const fallback = subpath === "." ? style : subpath
  for (const candidate of exported === null ? [fallback] : [exported, fallback]) {
    for (const file of [join(dir, candidate), join(dir, `${candidate}.css`)]) {
      if (file.endsWith(".css") && isFile(file)) return file
    }
  }
  return undefined
}

// A plugin or config module (`@plugin "@tailwindcss/typography"`) from the workspace, likewise.
export function workspaceModule(project: MockupProject, id: string, base: string): string | undefined {
  const name = bareName(id)
  if (name === null || installedAbove(base, name)) return undefined
  const located = locatePackage(project.resolution, name)
  if (located === null) return undefined
  try {
    return createRequire(join(located.from, "package.json")).resolve(id)
  } catch {
    return undefined
  }
}

async function compileCss(project: MockupProject, files: string[]): Promise<{ css: string; fonts: number }> {
  const tailwind = await loadTailwind(project)
  const from = project.css
  const compiler = await tailwind.compile(readFileSync(from, "utf8"), {
    base: dirname(from),
    from,
    onDependency: () => {},
    shouldRewriteUrls: true,
    customCssResolver: async (id, base) => workspaceStylesheet(project, id, base),
    customJsResolver: async (id, base) => workspaceModule(project, id, base),
  })
  const sources = files.map((file) => ({ base: dirname(file), pattern: basename(file), negated: false }))
  const candidates = new tailwind.Scanner({ sources }).scan()
  return inlineAssets(compiler.build(candidates), dirname(from))
}

export function entrySource(hasWrapper: boolean, state?: string): string {
  const screen = state === undefined ? `<Screen />` : `<Screen {...states[${JSON.stringify(state)}]} />`
  return [
    `import { createRoot } from "react-dom/client"`,
    `import Screen from "./screen"`,
    ...(state === undefined ? [] : [`import { states } from "./fixtures"`]),
    ...(hasWrapper ? [`import Wrapper from "../wrapper"`] : []),
    ``,
    `const root = document.getElementById("root")`,
    `if (root === null) throw new Error("the mockup page has no #root element")`,
    hasWrapper ? `createRoot(root).render(<Wrapper>${screen}</Wrapper>)` : `createRoot(root).render(${screen})`,
    ``,
  ].join("\n")
}

function writeEntry(mockup: string, state: string | undefined): string {
  const entry = join(mockup, ".entry.tsx")
  writeFileSync(entry, entrySource(existsSync(join(dirname(mockup), "wrapper.tsx")), state))
  return entry
}

const remoteImports = {
  name: "mockup-remote-imports",
  setup(build: {
    onResolve(
      options: { filter: RegExp },
      callback: (args: { path: string }) => { errors: { message: string }[] } | { path: string } | undefined,
    ): void
  }) {
    build.onResolve({ filter: /^(?:https?:)?\/\// }, (args) => ({
      errors: [{ message: `a mockup cannot import ${args.path}: the page loads nothing from the network` }],
    }))
  },
}

function cachedImports(cacheDirs: string[]) {
  return {
    name: "mockup-cached-imports",
    setup(build: {
      onResolve(
        options: { filter: RegExp },
        callback: (args: { path: string }) => { errors: { message: string }[] } | { path: string } | undefined,
      ): void
    }) {
      build.onResolve({ filter: /^@registry\// }, (args) => {
        const name = args.path.slice("@registry/".length)
        for (const dir of cacheDirs) {
          for (const extension of [".tsx", ".ts"]) {
            const file = join(dir, `${name}${extension}`)
            if (existsSync(file)) return { path: file }
          }
        }
        return {
          errors: [
            { message: `@registry/${name} is not in the registry cache; inspect --registry lists the item names` },
          ],
        }
      })
    },
  }
}

// A package the project's folder doesn't install but another workspace package does (react in a pnpm or Bun
// isolated workspace whose components package declares it only as a peer).
function workspacePackages(project: MockupProject): MockupBuildPlugin {
  return {
    name: "mockup-workspace-packages",
    setup(build) {
      build.onResolve({ filter: /^[^./#]/ }, (args) => {
        if (args.path.startsWith("@registry/")) return undefined
        if (project.pathPrefixes.some((prefix) => args.path.startsWith(prefix))) return undefined
        const name = bareName(args.path)
        const from = args.resolveDir ?? (args.importer === undefined ? undefined : dirname(args.importer))
        if (name === null || from === undefined || installedAbove(from, name)) return undefined
        const located = locatePackage(project.resolution, name)
        if (located === null) return undefined
        try {
          return { path: Bun.resolveSync(args.path, located.from) }
        } catch {
          return undefined
        }
      })
    },
  }
}

async function bundle(
  project: MockupProject,
  entry: string,
  outdir: string,
  cacheDirs: string[],
): Promise<{ js: string; map: string | null }> {
  const result = await Bun.build({
    entrypoints: [entry],
    outdir,
    target: "browser",
    format: "esm",
    minify: true,
    sourcemap: "external",
    define: { "process.env.NODE_ENV": '"production"' },
    loader: {
      ".png": "dataurl",
      ".jpg": "dataurl",
      ".jpeg": "dataurl",
      ".gif": "dataurl",
      ".svg": "dataurl",
      ".webp": "dataurl",
      ".avif": "dataurl",
    },
    plugins: [remoteImports, ...(cacheDirs.length === 0 ? [] : [cachedImports(cacheDirs)]), workspacePackages(project)],
  })
  if (!result.success) {
    const logs = result.logs.map((log) => `${log.level}: ${log.message}`).join("\n")
    throw new EnvironmentError(`the mockup bundle failed:\n${logs}`)
  }
  const js = result.outputs.find((output) => output.kind === "entry-point")
  const map = result.outputs.find((output) => output.kind === "sourcemap")
  if (js === undefined) throw new EnvironmentError("the mockup bundle produced no JavaScript")
  return {
    js: readFileSync(js.path, "utf8"),
    map: map === undefined ? null : readFileSync(map.path, "utf8"),
  }
}

function bundledFiles(map: string | null, mapDir: string): string[] {
  if (map === null) return []
  const parsed = JSON.parse(map) as { sources?: string[] }
  return (parsed.sources ?? [])
    .map((source) => resolve(mapDir, source))
    .filter((source) => !source.includes("\0") && existsSync(source) && statSync(source).isFile())
}

function inlineScript(js: string): string {
  return js.replaceAll(/<\/script/gi, "<\\/script")
}

function escapeAttribute(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll('"', "&quot;").replaceAll("<", "&lt;")
}

function htmlAttributes(settings: BuildSettings): string {
  const attributes = [`data-color-scheme="${settings.scheme}"`]
  if (settings.theme !== undefined) attributes.unshift(`data-theme="${escapeAttribute(settings.theme)}"`)
  if (settings.scheme !== "system") attributes.push(`class="${settings.scheme}"`)
  return attributes.join(" ")
}

function assemble(settings: BuildSettings, css: string, js: string): string {
  const template = readFileSync(join(dirname(fileURLToPath(import.meta.url)), "template.html"), "utf8")
  return template
    .replace("data-mockup-attributes", () => htmlAttributes(settings))
    .replace("{{title}}", () => escapeAttribute(settings.name))
    .replace("<!--mockup-style-->", () => `<style>${css}</style>`)
    .replace("<!--mockup-script-->", () => `<script type="module">${inlineScript(js)}</script>`)
}

function hashFile(path: string): string | null {
  return existsSync(path) ? createHash("sha256").update(readFileSync(path)).digest("hex").slice(0, 16) : null
}

function projectComponents(project: MockupProject, files: string[], mockup: string): string[] {
  const root = resolve(project.root)
  const owned = (file: string) => {
    const shown = relative(root, file)
    return !shown.startsWith("..") && !file.startsWith(mockup)
  }
  return [
    ...new Set(
      files
        .filter((file) => owned(file) && !/[\\/]node_modules[\\/]/.test(file))
        .map((file) => specifierOf(project, file))
        .filter((specifier): specifier is string => specifier !== null),
    ),
  ].toSorted()
}

function manifest(
  project: MockupProject,
  settings: BuildSettings,
  files: string[],
  sizes: { total: number; js: number; css: number; fonts: number },
  parts: { proposed: ProposedPart[]; sdkParts: SdkPart[]; gaps: Gap[] },
  install: InstallEntry[],
): MockupManifest {
  const mockup = mockupDirectory(project, settings.name)
  return {
    name: settings.name,
    date: new Date().toISOString(),
    theme: settings.theme ?? null,
    scheme: settings.scheme,
    state: settings.state ?? null,
    hashes: {
      screen: hashFile(join(mockup, "screen.tsx")),
      fixtures: hashFile(join(mockup, "fixtures.ts")),
    },
    components: projectComponents(project, files, mockup),
    install,
    proposed: parts.proposed,
    sdkParts: parts.sdkParts,
    gaps: parts.gaps,
    size: { total: sizes.total, js: sizes.js, css: sizes.css, fonts: sizes.fonts },
  }
}

export function mockupSourceFiles(mockup: string): string[] {
  const found: string[] = []
  const visit = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.name.startsWith(".")) continue
      const path = join(dir, entry.name)
      if (entry.isDirectory()) {
        visit(path)
        continue
      }
      if (/\.(ts|tsx)$/.test(entry.name)) found.push(path)
    }
  }
  if (existsSync(mockup)) visit(mockup)
  return found.toSorted()
}

// The theme segment of a page's name: a theme such as compact, or else the colour scheme.
export function pageTheme(settings: Pick<BuildSettings, "theme" | "scheme">): string {
  return settings.theme ?? settings.scheme
}

// The files written for the mockup (screen, fixtures, parts, gaps) and the shared wrapper, not the
// installed components or the registry cache they import.
function ownFiles(mockup: string): string[] {
  const wrapper = join(dirname(mockup), "wrapper.tsx")
  return [...mockupSourceFiles(mockup), ...(existsSync(wrapper) ? [wrapper] : [])]
}

export async function buildMockup(project: MockupProject, settings: BuildSettings): Promise<BuildOutcome> {
  const mockup = mockupDirectory(project, settings.name)
  const screen = join(mockup, "screen.tsx")
  if (!existsSync(screen)) {
    throw new EnvironmentError(`no mockup named ${settings.name}: ${displayPath(screen, settings.cwd)} does not exist`)
  }
  mkdirSync(dirname(mockup), { recursive: true })
  writeFileSync(join(project.root, ".mockups", ".gitignore"), "*\n")

  const parts = await readMockupParts(mockup, settings.cwd)
  const registry = await prepareRegistry(project, mockup, mockupSourceFiles(mockup))

  const entry = writeEntry(mockup, settings.state)
  const outdir = mkdtempSync(join(tmpdir(), "eskais-mockup-"))
  let built: { js: string; map: string | null }
  let files: string[]
  try {
    built = await bundle(project, entry, outdir, registry.cacheDirs)
    files = bundledFiles(built.map, outdir)
  } finally {
    rmSync(entry, { force: true })
    rmSync(outdir, { recursive: true, force: true })
  }
  const { css, fonts } = await compileCss(project, files)
  const page = assemble(settings, css, built.js)

  const outPath =
    settings.out === undefined
      ? join(mockup, settings.state === undefined ? "out.html" : stateOutName(settings.state, pageTheme(settings)))
      : resolve(settings.cwd, settings.out)
  mkdirSync(dirname(outPath), { recursive: true })
  writeFileSync(outPath, page)

  const sizes = {
    total: Buffer.byteLength(page),
    js: Buffer.byteLength(built.js),
    css: Buffer.byteLength(css),
    fonts,
  }
  const problems = [
    ...pageProblems(page).map((message) => ({
      file: displayPath(outPath, settings.cwd),
      line: 1,
      column: 1,
      rule: "page",
      message,
    })),
    ...ownFiles(mockup).flatMap((file) =>
      viewportProblems(displayPath(file, settings.cwd), readFileSync(file, "utf8")),
    ),
  ]
  const outcome: BuildOutcome = {
    outPath,
    manifestPath: join(mockup, "manifest.json"),
    ...sizes,
    problems,
    warnings: [],
    manifest: manifest(project, settings, files, sizes, parts, registry.install),
    parts,
  }
  const banner = reactDevBanner(built.js)
  if (banner !== undefined) {
    outcome.problems.push({
      file: displayPath(outPath, settings.cwd),
      line: 1,
      column: 1,
      rule: "page",
      message: `bundles the React development build (${banner})`,
    })
  }
  if (outcome.total > SIZE_WARNING) {
    outcome.warnings.push(
      `${displayPath(outPath, settings.cwd)} is ${formatSize(outcome.total)}: the first paint may stall`,
    )
  }
  writeFileSync(outcome.manifestPath, `${JSON.stringify(outcome.manifest, null, 2)}\n`)
  return outcome
}

export function summary(outcome: BuildOutcome, cwd: string): string {
  const split = `(${formatSize(outcome.js)} js, ${formatSize(outcome.css)} css, ${formatSize(outcome.fonts)} fonts)`
  return `${displayPath(outcome.outPath, cwd)}  ${formatSize(outcome.total)} ${split}`
}

export type Problem = {
  file: string
  line: number
  column: number
  rule: string
  message: string
}

export const DEFAULT_MAX_PROBLEMS = 20

const VIEWPORT_HEIGHT_UNIT = /\b\d+(\.\d+)?[dls]?vh\b|\b(min-|max-)?h-(screen|[dls]?vh)\b/
const VIEWPORT_HEIGHT_UNITS = new RegExp(VIEWPORT_HEIGHT_UNIT.source, "g")
const REACT_DEV_BANNER = /Download the React DevTools[^"`]{0,40}/
const TEMPLATE_PLACEHOLDER = /data-mockup-attributes|<!--mockup-(style|script)-->|\{\{title\}\}/

const BARE_CONTROLS = /<(button|input|select|textarea)\b/g
const NETWORK_CALL = /\bfetch\s*\(|\b(?:XMLHttpRequest|WebSocket|EventSource)\b/g
const IMPORT_SPECIFIER =
  /\bimport\s+(?:type\s+)?(?:[^"'`;]*?\bfrom\s*)?["']([^"']+)["']|\bimport\s*\(\s*["']([^"']+)["']/g
const RAWS =
  /\b(?:bg|text|border|ring|fill|stroke|from|via|to|outline|decoration|divide|shadow|accent|caret|placeholder)-(?:white|black)\b|\b(?:bg|text|border|ring|fill|stroke|from|via|to|outline|decoration|divide|shadow|accent|caret|placeholder)-\[[^\]\n]*?(?:#[0-9a-fA-F]{3,8}|rgba?\(|hsla?\(|oklch\(|color\()|\b(?:color|background|backgroundColor|borderColor|fill|stroke)\s*:\s*["'](?:#[0-9a-fA-F]{3,8}|rgba?\(|hsla?\(|oklch\()/g
const ARBITRARY_VALUES =
  /\b(?:w|h|size|min-w|min-h|max-w|max-h|p|px|py|pt|pb|pl|pr|m|mx|my|mt|mb|ml|mr|gap|space-x|space-y|inset|top|right|bottom|left|start|end|text|leading|tracking|rounded|basis|grid-cols|grid-rows|translate-x|translate-y)-\[[^\]\n]+\]/g
const ALLOWED_ARBITRARY = new Set(["max-h-[calc(100%-2rem)]", "w-[calc(100%-2rem)]"])

export type ImportedSpecifier = { specifier: string; line: number; column: number }

export function importsOf(source: string): ImportedSpecifier[] {
  return [...source.matchAll(IMPORT_SPECIFIER)].map((match) => ({
    specifier: match[1] ?? match[2] ?? "",
    ...position(source, match.index),
  }))
}

export function viewportHeightUnit(page: string): string | undefined {
  return page.match(VIEWPORT_HEIGHT_UNIT)?.[0]
}

export function reactDevBanner(bundle: string): string | undefined {
  return bundle.match(REACT_DEV_BANNER)?.[0]
}

export function pageProblems(page: string): string[] {
  const markup = page
    .replaceAll(/<script\b(?![^>]*\bsrc=)[^>]*>[\s\S]*?<\/script>/gi, "")
    .replaceAll(/<style\b[^>]*>[\s\S]*?<\/style>/gi, "")
  const styles = [...page.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)].map((match) => match[1]).join("\n")
  const problems: string[] = []
  if (/<script[^>]+src=/i.test(markup)) problems.push("still loads an external script")
  if (/<link[^>]+rel="?(stylesheet|preload|modulepreload)/i.test(markup)) {
    problems.push("still loads an external stylesheet")
  }
  if (/<img[^>]+src="?(?!data:)/i.test(markup)) problems.push("still loads an external image")
  if (/@import\b/i.test(styles)) problems.push("still imports a stylesheet")
  if (/url\((?!\s*["']?data:)/i.test(styles)) problems.push("still loads an asset that is not inlined")
  if (TEMPLATE_PLACEHOLDER.test(page)) problems.push("still has a template placeholder")
  return problems
}

export function position(source: string, index: number): { line: number; column: number } {
  const before = source.slice(0, Math.max(0, index))
  return { line: before.split("\n").length, column: index - before.lastIndexOf("\n") }
}

function matches(
  source: string,
  pattern: RegExp,
  build: (match: RegExpExecArray) => { rule: string; message: string } | null,
): Omit<Problem, "file">[] {
  const found: { at: number; problem: Omit<Problem, "file"> }[] = []
  for (const match of source.matchAll(pattern)) {
    const built = build(match)
    if (built === null) continue
    found.push({ at: match.index, problem: { ...built, ...position(source, match.index) } })
  }
  return found.toSorted((left, right) => left.at - right.at).map((entry) => entry.problem)
}

function importName(specifier: string): string {
  return specifier.startsWith("@") ? specifier.split("/").slice(0, 2).join("/") : (specifier.split("/")[0] ?? "")
}

export function importRule(prefixes: string[], dependencies: Set<string>): (specifier: string) => boolean {
  return (specifier) => {
    if (specifier.startsWith(".")) return true
    if (prefixes.some((prefix) => specifier.startsWith(prefix))) return true
    return dependencies.has(importName(specifier))
  }
}

export function sourceProblems(file: string, source: string, allowed: (specifier: string) => boolean): Problem[] {
  const problems = [
    ...matches(source, NETWORK_CALL, (match) => ({
      rule: "no-network",
      message: `${match[0].replace(/\s+$/, "")} calls the network; a mockup is one offline file`,
    })),
    ...matches(source, BARE_CONTROLS, (match) => ({
      rule: "bare-control",
      message: `a bare <${match[1] ?? "button"}> is invisible to agents and unstyled; use the project's own control part`,
    })),
    ...matches(source, IMPORT_SPECIFIER, (match) => {
      const specifier = match[1] ?? match[2] ?? ""
      return allowed(specifier)
        ? null
        : {
            rule: "import-specifier",
            message: `"${specifier}" is not the project's: import through an alias, a relative path or a dependency`,
          }
    }),
  ]
  return problems
    .map((problem) => ({ ...problem, file }))
    .toSorted((left, right) => left.line - right.line || left.column - right.column)
}

export function sdkImportProblems(file: string, source: string, publicSpecifiers: Set<string>): Problem[] {
  const problems = importsOf(source)
    .filter(({ specifier }) => specifier.startsWith("@ui-sdk/"))
    .flatMap(({ specifier, line, column }) => {
      if (publicSpecifiers.has(specifier)) return []
      const bare = !specifier.slice("@ui-sdk/".length).includes("/")
      return [
        {
          file,
          line,
          column,
          rule: "sdk-subpath",
          message: bare
            ? `import @ui-sdk from a public subpath, like "${specifier}/dialog"`
            : `"${specifier}" is not a public @ui-sdk subpath of an installed package`,
        },
      ]
    })
  return problems
}

// Only the mockup's own files: an installed block may size itself to the viewport (Shell sets
// --shell-height: 100dvh), and the bundle and stylesheet carry every installed component.
export function viewportProblems(file: string, source: string): Problem[] {
  return matches(source, VIEWPORT_HEIGHT_UNITS, (match) => ({
    rule: "viewport-unit",
    message: `${match[0]} is a viewport height unit; size the screen from its container (h-full, min-h-full)`,
  })).map((problem) => ({ ...problem, file }))
}

export function partStyleProblems(file: string, source: string): Problem[] {
  const problems = [
    ...matches(source, RAWS, (match) => ({
      rule: "shadcn/no-raw-colors",
      message: `${match[0]} is a raw colour; use a theme token (bg-card, text-muted-foreground, border-input)`,
    })),
    ...matches(source, ARBITRARY_VALUES, (match) =>
      ALLOWED_ARBITRARY.has(match[0]) || /#[0-9a-fA-F]{3,8}|rgba?\(|hsla?\(|oklch\(|color\(/.test(match[0])
        ? null
        : {
            rule: "shadcn/no-arbitrary-values",
            message: `${match[0]} is an arbitrary size; use the Tailwind scale or a theme token`,
          },
    ),
  ]
  return problems
    .map((problem) => ({ ...problem, file }))
    .toSorted((left, right) => left.line - right.line || left.column - right.column)
}

export function formatProblem(problem: Problem): string {
  return `${problem.file}:${problem.line}:${problem.column} ${problem.rule} ${problem.message}`
}

export function formatProblems(problems: Problem[], max: number): string[] {
  const shown = problems.slice(0, max).map(formatProblem)
  if (problems.length > max) shown.push(`… ${problems.length - max} more problems (raise --max to see them)`)
  return shown
}

import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs"
import { basename, dirname, join, relative, sep } from "node:path"

import { displayPath, EnvironmentError } from "./project"

export const GALLERY_FILE = "gallery.html"

export type Screenshot = {
  screen: string
  state: string
  theme: string
  png: string
  html: string | null
  width: number | null
  height: number | null
}

export type GalleryScan = {
  dir: string
  screenshots: Screenshot[]
  pagesWithoutScreenshot: string[]
}

const SCHEMES = new Set(["light", "dark", "system"])
const THEME_ORDER = ["light", "dark", "system"]
export const DEFAULT_STATE = "default"
export const DEFAULT_THEME = "system"

export function parseVariant(file: string): { state: string; theme: string } {
  const stem = basename(file).replace(/\.(png|html)$/i, "")
  const rest = stem.replace(/^out(?:-|$)/, "")
  const segments = rest === "" ? [] : rest.split("-")
  if (segments.length === 0) return { state: DEFAULT_STATE, theme: DEFAULT_THEME }
  if (segments.length === 1) {
    const only = segments[0] ?? ""
    return SCHEMES.has(only) ? { state: DEFAULT_STATE, theme: only } : { state: only, theme: DEFAULT_THEME }
  }
  return { state: segments.slice(0, -1).join("-"), theme: segments.at(-1) ?? DEFAULT_THEME }
}

function pngSize(file: string): { width: number | null; height: number | null } {
  const bytes = readFileSync(file)
  const signature = bytes.subarray(1, 4).toString("latin1")
  if (bytes.length < 24 || signature !== "PNG") return { width: null, height: null }
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20) }
}

function walk(dir: string, found: { png: string[]; html: string[] }) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith(".") || entry.name === "node_modules") continue
    const path = join(dir, entry.name)
    if (entry.isDirectory()) {
      walk(path, found)
      continue
    }
    if (!/^out[-.]/i.test(entry.name)) continue
    if (/\.png$/i.test(entry.name)) found.png.push(path)
    else if (/\.html$/i.test(entry.name)) found.html.push(path)
  }
}

function rank(order: string[], value: string): number {
  const index = order.indexOf(value)
  return index === -1 ? order.length : index
}

function compareScreenshots(left: Screenshot, right: Screenshot): number {
  return (
    left.screen.localeCompare(right.screen) ||
    rank([DEFAULT_STATE], left.state) - rank([DEFAULT_STATE], right.state) ||
    left.state.localeCompare(right.state) ||
    rank(THEME_ORDER, left.theme) - rank(THEME_ORDER, right.theme) ||
    left.theme.localeCompare(right.theme)
  )
}

export function scanScreenshots(dir: string): GalleryScan {
  if (!existsSync(dir) || !statSync(dir).isDirectory()) {
    throw new EnvironmentError(`gallery needs a folder: ${dir} is not one`)
  }
  const found = { png: [] as string[], html: [] as string[] }
  walk(dir, found)
  const pages = new Set(found.html)
  const screenshots = found.png.map((png): Screenshot => {
    const html = png.replace(/\.png$/i, ".html")
    const folder = dirname(png)
    const screen = folder === dir ? basename(dir) : relative(dir, folder).split(sep).join("/")
    return { screen, ...parseVariant(png), png, html: pages.has(html) ? html : null, ...pngSize(png) }
  })
  const shot = new Set(screenshots.map((entry) => entry.html))
  const pagesWithoutScreenshot = found.html.filter((page) => !shot.has(page)).toSorted()
  return { dir, screenshots: screenshots.toSorted(compareScreenshots), pagesWithoutScreenshot }
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;")
}

function href(from: string, file: string): string {
  return relative(from, file).split(sep).map(encodeURIComponent).join("/")
}

function slug(value: string): string {
  return (
    value
      .toLowerCase()
      .replaceAll(/[^a-z0-9]+/g, "-")
      .replaceAll(/^-|-$/g, "") || "screen"
  )
}

export function altText(entry: Pick<Screenshot, "screen" | "state" | "theme">): string {
  return `${entry.screen}, ${entry.state} state, ${entry.theme} theme`
}

function plural(count: number, word: string): string {
  return `${count} ${word}${count === 1 ? "" : "s"}`
}

function groupBy<T>(items: T[], key: (item: T) => string): [string, T[]][] {
  const groups = new Map<string, T[]>()
  for (const item of items) {
    const name = key(item)
    const group = groups.get(name)
    if (group === undefined) groups.set(name, [item])
    else group.push(item)
  }
  return [...groups]
}

export function countSummary(scan: GalleryScan): string {
  const screens = new Set(scan.screenshots.map((entry) => entry.screen)).size
  const states = new Set(scan.screenshots.map((entry) => `${entry.screen}\0${entry.state}`)).size
  const themes = new Set(scan.screenshots.map((entry) => entry.theme)).size
  return `${plural(scan.screenshots.length, "screenshot")}: ${plural(screens, "screen")}, ${plural(states, "state")}, ${plural(themes, "theme")}`
}

const STYLE = `
:root { color-scheme: light dark; font-family: system-ui, sans-serif; line-height: 1.5; }
body { margin: 0; background: Canvas; color: CanvasText; }
main { max-width: 80rem; margin: 0 auto; padding: 1.5rem 1rem 4rem; }
h1 { font-size: 1.75rem; margin: 0 0 0.25rem; }
h2 { font-size: 1.375rem; margin: 2.5rem 0 0.5rem; border-bottom: 1px solid color-mix(in srgb, CanvasText 20%, transparent); padding-bottom: 0.25rem; }
h3 { font-size: 1.0625rem; margin: 1.5rem 0 0.5rem; }
nav ul { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; padding: 0; list-style: none; }
ul.shots { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(22rem, 100%), 1fr)); gap: 1rem; padding: 0; margin: 0; list-style: none; }
figure { margin: 0; }
figure img { display: block; width: 100%; height: auto; border: 1px solid color-mix(in srgb, CanvasText 25%, transparent); border-radius: 0.5rem; background: color-mix(in srgb, CanvasText 6%, Canvas); }
figcaption { font-size: 0.875rem; margin-top: 0.375rem; overflow-wrap: anywhere; }
code { font-family: ui-monospace, monospace; font-size: 0.8125rem; }
a { color: LinkText; }
a:focus-visible { outline: 3px solid Highlight; outline-offset: 3px; border-radius: 0.5rem; }
.missing { color: color-mix(in srgb, CanvasText 70%, Canvas); }
`

function figure(scan: GalleryScan, entry: Screenshot): string {
  const size = entry.width === null || entry.height === null ? "" : ` width="${entry.width}" height="${entry.height}"`
  const image = `<img src="${href(scan.dir, entry.png)}" alt="${escapeHtml(altText(entry))}" loading="lazy" decoding="async"${size}>`
  const page =
    entry.html === null
      ? `<span class="missing">no page beside it</span>`
      : `<code>${escapeHtml(relative(scan.dir, entry.html).split(sep).join("/"))}</code>`
  const body = entry.html === null ? image : `<a href="${href(scan.dir, entry.html)}">${image}</a>`
  return `<li><figure>${body}<figcaption>${escapeHtml(entry.theme)} theme · ${page}</figcaption></figure></li>`
}

export function galleryHtml(scan: GalleryScan, title = "Mockups"): string {
  const screens = groupBy(scan.screenshots, (entry) => entry.screen)
  const ids = new Map<string, string>()
  for (const [screen] of screens) {
    let id = `screen-${slug(screen)}`
    while ([...ids.values()].includes(id)) id = `${id}-x`
    ids.set(screen, id)
  }
  const nav = screens
    .map(
      ([screen, shots]) => `<li><a href="#${ids.get(screen) ?? ""}">${escapeHtml(screen)} (${shots.length})</a></li>`,
    )
    .join("")
  const sections = screens
    .map(([screen, shots]) => {
      const id = ids.get(screen) ?? ""
      const states = groupBy(shots, (entry) => entry.state)
        .map(
          ([state, entries]) =>
            `<section aria-label="${escapeHtml(`${screen}, ${state} state`)}"><h3>${escapeHtml(state)} state</h3><ul class="shots">${entries.map((entry) => figure(scan, entry)).join("")}</ul></section>`,
        )
        .join("")
      return `<section aria-labelledby="${id}"><h2 id="${id}">${escapeHtml(screen)}</h2>${states}</section>`
    })
    .join("\n")
  const missing =
    scan.pagesWithoutScreenshot.length === 0
      ? ""
      : `<section aria-labelledby="missing"><h2 id="missing">Pages without a screenshot</h2><ul>${scan.pagesWithoutScreenshot
          .map(
            (page) =>
              `<li><a href="${href(scan.dir, page)}"><code>${escapeHtml(relative(scan.dir, page).split(sep).join("/"))}</code></a></li>`,
          )
          .join("")}</ul></section>`
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${STYLE}</style>
</head>
<body>
<main>
<h1>${escapeHtml(title)}</h1>
<p data-gallery-count="${scan.screenshots.length}">${escapeHtml(countSummary(scan))}</p>
<nav aria-label="Screens"><ul>${nav}</ul></nav>
${sections}
${missing}
</main>
</body>
</html>
`
}

export type GalleryOutcome = { path: string | null; scan: GalleryScan }

export function writeGallery(dir: string): GalleryOutcome {
  const scan = scanScreenshots(dir)
  if (scan.screenshots.length === 0) return { path: null, scan }
  const path = join(dir, GALLERY_FILE)
  writeFileSync(path, galleryHtml(scan))
  return { path, scan }
}

export function galleryHeadline(outcome: GalleryOutcome, cwd: string): string {
  if (outcome.path === null) {
    return `no screenshots in ${displayPath(outcome.scan.dir, cwd)}: capture each out*.html as a PNG with the same name beside it (out-empty-dark.html → out-empty-dark.png), then run gallery again`
  }
  return `gallery ${displayPath(outcome.path, cwd)}  ${countSummary(outcome.scan)}`
}

export function galleryLines(outcome: GalleryOutcome, cwd: string): string[] {
  const { scan } = outcome
  const missing = scan.pagesWithoutScreenshot.map(
    (page) => `no screenshot: ${displayPath(page, cwd)} (capture it as ${basename(page).replace(/\.html$/i, ".png")})`,
  )
  const shots = scan.screenshots.map(
    (entry) =>
      `${entry.screen}  ${entry.state}  ${entry.theme}  ${displayPath(entry.png, cwd)}  ${entry.html === null ? "(no page)" : displayPath(entry.html, cwd)}`,
  )
  return outcome.path === null
    ? [galleryHeadline(outcome, cwd), ...missing]
    : [...shots, ...missing, galleryHeadline(outcome, cwd)]
}

export function galleryJson(outcome: GalleryOutcome, cwd: string) {
  return {
    gallery: outcome.path === null ? null : displayPath(outcome.path, cwd),
    count: outcome.scan.screenshots.length,
    screenshots: outcome.scan.screenshots.map((entry) => ({
      screen: entry.screen,
      state: entry.state,
      theme: entry.theme,
      png: displayPath(entry.png, cwd),
      html: entry.html === null ? null : displayPath(entry.html, cwd),
    })),
    pagesWithoutScreenshot: outcome.scan.pagesWithoutScreenshot.map((page) => displayPath(page, cwd)),
  }
}

export function screenshotSummary(dir: string): string {
  const scan = scanScreenshots(dir)
  const pages = scan.screenshots.filter((entry) => entry.html !== null).length + scan.pagesWithoutScreenshot.length
  const missing =
    scan.pagesWithoutScreenshot.length === 0
      ? ""
      : `; no screenshot: ${scan.pagesWithoutScreenshot.map((page) => basename(page)).join(", ")}`
  return `screenshots ${scan.screenshots.length} (${plural(pages, "page")}${missing})`
}

import { existsSync, readFileSync, readdirSync } from "node:fs"
import { basename, dirname, join, relative, resolve } from "node:path"

import { displayPath, EnvironmentError, type MockupProject, type ProjectAlias } from "./project"

export type ExportKind = "value" | "type"

export type ExportedName = {
  name: string
  kind: ExportKind
}

export type AliasFile = {
  alias: string
  path: string
  shown: string
  specifier: string
  exports: ExportedName[]
}

export type ComponentDetail = {
  name: string
  kind: ExportKind
  specifier: string
  file: string
  importLine: string
  propsImport: string | null
  props: string | null
  variants: string[]
}

const DECLARATIONS: { pattern: RegExp; kind: ExportKind }[] = [
  { pattern: /export\s+(?:default\s+)?(?:async\s+)?function\s*\*?\s*([A-Za-z_$][\w$]*)/g, kind: "value" },
  { pattern: /export\s+(?:default\s+)?(?:abstract\s+)?class\s+([A-Za-z_$][\w$]*)/g, kind: "value" },
  { pattern: /export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)/g, kind: "value" },
  { pattern: /export\s+(?:declare\s+)?enum\s+([A-Za-z_$][\w$]*)/g, kind: "value" },
  { pattern: /export\s+type\s+([A-Za-z_$][\w$]*)\s*[=<]/g, kind: "type" },
  { pattern: /export\s+interface\s+([A-Za-z_$][\w$]*)/g, kind: "type" },
]

const RE_EXPORTS = /export\s+(?:type\s+)?\{([^}]*)\}/g

export function readExports(source: string): ExportedName[] {
  const found: ExportedName[] = []
  const add = (name: string, kind: ExportKind) => {
    if (name === "" || name === "default" || found.some((entry) => entry.name === name)) return
    found.push({ name, kind })
  }
  const positions: { at: number; name: string; kind: ExportKind }[] = []
  for (const { pattern, kind } of DECLARATIONS) {
    for (const match of source.matchAll(pattern)) {
      const name = match[1]
      if (name !== undefined) positions.push({ at: match.index, name, kind })
    }
  }
  for (const match of source.matchAll(RE_EXPORTS)) {
    const body = match[1] ?? ""
    const typeOnly = /^export\s+type\s*\{/.test(match[0])
    let offset = match.index + match[0].indexOf("{") + 1
    for (const part of body.split(",")) {
      const cleaned = part.replace(/^\s*type\s+/, "").trim()
      const name =
        cleaned
          .split(/\s+as\s+/)
          .at(-1)
          ?.trim() ?? ""
      if (name !== "")
        positions.push({ at: offset, name, kind: typeOnly || /^\s*type\s/.test(part) ? "type" : "value" })
      offset += part.length + 1
    }
  }
  for (const entry of positions.toSorted((left, right) => left.at - right.at)) add(entry.name, entry.kind)
  return found
}

function blockEnd(source: string, openIndex: number): number {
  const open = source[openIndex]
  const close = open === "(" ? ")" : open === "{" ? "}" : "]"
  let depth = 0
  for (let index = openIndex; index < source.length; index += 1) {
    const char = source[index]
    if (char === open) depth += 1
    if (char === close) {
      depth -= 1
      if (depth === 0) return index + 1
    }
  }
  return source.length
}

function declarationEnd(source: string, from: number): number {
  let depth = 0
  for (let index = from; index < source.length; index += 1) {
    const char = source[index]
    if (char === "{" || char === "(" || char === "[") depth += 1
    if (char === "}" || char === ")" || char === "]") {
      if (depth === 0) return index
      depth -= 1
    }
    if (char !== "\n" || depth > 0) continue
    const tail = source.slice(from, index).trimEnd()
    const next = source.slice(index + 1).match(/^\s*(\S)/)?.[1]
    if (next === undefined) return index
    if (!/[&|,=(:<]$/.test(tail) && !/^[&|)]/.test(next)) return index
  }
  return source.length
}

export function extractType(source: string, name: string): string | null {
  const match = new RegExp(`\\b(type|interface)\\s+${name}\\b\\s*(?:<|=|\\{|extends\\b)`).exec(source)
  if (match === null) return null
  const start = match.index
  if (match[1] === "interface") {
    const open = source.indexOf("{", start)
    if (open === -1) return null
    return source.slice(start, blockEnd(source, open)).trimEnd()
  }
  const equal = source.indexOf("=", start)
  if (equal === -1) return null
  return source.slice(start, declarationEnd(source, equal + 1)).trimEnd()
}

export function extractCva(source: string): { name: string; text: string }[] {
  const found: { name: string; text: string }[] = []
  for (const match of source.matchAll(/\bconst\s+([A-Za-z_$][\w$]*)\s*=\s*cva\s*\(/g)) {
    const open = match.index + match[0].length - 1
    found.push({ name: match[1] ?? "", text: source.slice(match.index, blockEnd(source, open)).trimEnd() })
  }
  return found
}

type DirectoryAlias = ProjectAlias & { dir: string }

function aliasedFiles(project: MockupProject): AliasFile[] {
  const directories = project.aliases.filter((alias): alias is DirectoryAlias => alias.dir !== null)
  const claimed = new Map<string, { alias: DirectoryAlias; path: string }>()
  for (const alias of directories) {
    for (const path of readSourceFiles(alias.dir)) {
      const key = path.toLowerCase()
      const current = claimed.get(key)
      if (current !== undefined && current.alias.dir.length >= alias.dir.length) continue
      claimed.set(key, { alias, path })
    }
  }
  return [...claimed.values()]
    .map(({ alias, path }) => ({
      alias: alias.name,
      path,
      shown: relative(alias.dir, path)
        .replaceAll("\\", "/")
        .replace(/\.(tsx|ts)$/, ""),
      specifier: specifierOfPath(alias.specifier, alias.dir, path),
      exports: readExports(readFileSync(path, "utf8")),
    }))
    .toSorted((left, right) => left.path.localeCompare(right.path))
}

function specifierOfPath(aliasSpecifier: string, aliasDir: string, path: string): string {
  const shown = relative(aliasDir, path)
    .replaceAll("\\", "/")
    .replace(/\.(tsx|ts)$/, "")
  return `${aliasSpecifier}/${shown}`
}

function readSourceFiles(dir: string): string[] {
  const files: string[] = []
  const visit = (current: string) => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      if (entry.name.startsWith(".") || entry.name === "node_modules") continue
      const path = join(current, entry.name)
      if (entry.isDirectory()) {
        visit(path)
        continue
      }
      if (!/\.(ts|tsx)$/.test(entry.name)) continue
      if (/\.(test|spec)\./.test(entry.name) || entry.name.endsWith(".d.ts")) continue
      files.push(path)
    }
  }
  visit(dir)
  return files.toSorted()
}

function providerNames(project: MockupProject): string[] {
  if (project.entry === null) return []
  const source = readFileSync(project.entry, "utf8")
  const names = new Set<string>()
  for (const match of source.matchAll(/\b([A-Z]\w*Provider)\b/g)) names.add(match[1] ?? "")
  return [...names].filter((name) => name !== "").toSorted()
}

function collectThemes(project: MockupProject): string[] {
  const seen = new Set<string>()
  const names = new Set<string>()
  const visit = (file: string, depth: number) => {
    const key = file.toLowerCase()
    if (depth > 4 || seen.has(key) || !existsSync(file)) return
    seen.add(key)
    const css = readFileSync(file, "utf8")
    for (const match of css.matchAll(/\[data-theme\s*=\s*["']?([\w-]+)/g)) names.add(match[1] ?? "")
    for (const match of css.matchAll(/@import\s+(?:url\()?\s*["']([^"']+)["']/g)) {
      const href = match[1] ?? ""
      if (href.startsWith(".")) visit(resolve(dirname(file), href), depth + 1)
    }
  }
  visit(project.css, 0)
  return ["default", ...names].filter((name, index, all) => all.indexOf(name) === index).toSorted()
}

export function wrapperFile(project: MockupProject): string | null {
  const file = join(project.root, ".mockups", "wrapper.tsx")
  return existsSync(file) ? file : null
}

export function indexText(project: MockupProject, cwd: string): string {
  const wrapper = wrapperFile(project)
  const lines = [
    `project ${displayPath(project.root, cwd)}`,
    `css ${displayPath(project.css, cwd)}`,
    `tailwind ${project.runtime.tailwindVersion}  react ${project.runtime.reactVersion}`,
    `entry ${project.entry === null ? "none" : displayPath(project.entry, cwd)}`,
    `providers ${providerNames(project).join(", ") || "none"}`,
    `themes ${collectThemes(project).join(", ")}`,
    `wrapper ${wrapper === null ? "none" : displayPath(wrapper, cwd)}`,
    "",
  ]
  const files = aliasedFiles(project)
  for (const alias of project.aliases) {
    if (alias.dir === null) continue
    const inAlias = files.filter((file) => file.alias === alias.name)
    lines.push(`${alias.name} (${displayPath(alias.dir, cwd)})`)
    for (const file of inAlias) {
      const names = file.exports.filter((entry) => entry.kind === "value").map((entry) => entry.name)
      if (names.length === 0) continue
      lines.push(`  ${file.shown} ${names.join(", ")}`)
    }
  }
  return lines.join("\n").trimEnd()
}

function kebab(name: string): string {
  return name
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1-$2")
    .toLowerCase()
}

export function componentDetail(project: MockupProject, name: string): ComponentDetail {
  const files = aliasedFiles(project)
  const declared = files.filter((file) => file.exports.some((entry) => entry.name === name))
  const byFile = declared.find((file) => basename(file.path).replace(/\.(tsx|ts)$/, "") === kebab(name))
  const file = byFile ?? declared[0]
  if (file === undefined) {
    throw new EnvironmentError(`no file in the project's aliases exports ${name}`)
  }
  const source = readFileSync(file.path, "utf8")
  const entry = file.exports.find((exported) => exported.name === name)
  if (entry === undefined) throw new EnvironmentError(`${name} is not exported by ${file.path}`)
  const variants = extractCva(source)
  const related = variants.filter((variant) => variant.name.toLowerCase().includes(name.toLowerCase().slice(0, 4)))
  const props = entry.kind === "type" ? null : extractType(source, `${name}Props`)
  const importNames = [name, ...related.map((variant) => variant.name)]
  const importLine = `${entry.kind === "type" ? "import type" : "import"} { ${importNames.join(", ")} } from "${file.specifier}"`
  return {
    name,
    kind: entry.kind,
    specifier: file.specifier,
    file: file.path,
    importLine,
    propsImport: props === null ? null : `import type { ${name}Props } from "${file.specifier}"`,
    props,
    variants: related.map((variant) => variant.text),
  }
}

export function detailText(detail: ComponentDetail, cwd: string): string {
  const lines = [`${detail.specifier}  (${displayPath(detail.file, cwd)})`, detail.importLine]
  if (detail.propsImport !== null) lines.push(detail.propsImport)
  if (detail.props !== null) lines.push(detail.props)
  for (const variant of detail.variants) lines.push(variant)
  return lines.join("\n")
}

export function detailJson(detail: ComponentDetail, cwd: string) {
  return {
    name: detail.name,
    kind: detail.kind,
    specifier: detail.specifier,
    file: displayPath(detail.file, cwd),
    importLine: detail.importLine,
    propsImport: detail.propsImport,
    props: detail.props,
    variants: detail.variants,
  }
}

export function indexJson(project: MockupProject, cwd: string) {
  const files = aliasedFiles(project)
  const wrapper = wrapperFile(project)
  return {
    project: displayPath(project.root, cwd),
    css: displayPath(project.css, cwd),
    entry: project.entry === null ? null : displayPath(project.entry, cwd),
    tailwind: project.runtime.tailwindVersion,
    react: project.runtime.reactVersion,
    providers: providerNames(project),
    themes: collectThemes(project),
    wrapper: wrapper === null ? null : displayPath(wrapper, cwd),
    aliases: project.aliases.map((alias) => ({
      name: alias.name,
      specifier: alias.specifier,
      dir: alias.dir === null ? null : displayPath(alias.dir, cwd),
      files: files
        .filter((file) => file.alias === alias.name)
        .map((file) => ({ file: file.shown, specifier: file.specifier, exports: file.exports })),
    })),
  }
}

// Node's package `imports` and `exports` maps: exact keys, one-star patterns (longest prefix wins),
// condition objects in key order and fallback arrays, as in the PACKAGE_TARGET_RESOLVE algorithm.

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

// The source of an app's own files, as TypeScript's bundler resolution and Bun read them. "types" is left out
// so a map that sends types to a dist folder still leads to the sources.
export const SOURCE_CONDITIONS = ["browser", "import", "module", "bun", "development", "default", "node", "require"]

export const STYLE_CONDITIONS = ["style", "default"]

export function targetOf(value: unknown, conditions: readonly string[]): string | null {
  if (typeof value === "string") return value
  if (Array.isArray(value)) {
    for (const entry of value) {
      const target = targetOf(entry, conditions)
      if (target !== null) return target
    }
    return null
  }
  if (!isRecord(value)) return null
  for (const [key, entry] of Object.entries(value)) {
    if (!conditions.includes(key)) continue
    const target = targetOf(entry, conditions)
    if (target !== null) return target
  }
  return null
}

export function matchMap(map: unknown, specifier: string, conditions: readonly string[]): string | null {
  if (!isRecord(map)) return null
  if (Object.hasOwn(map, specifier) && !specifier.includes("*")) return targetOf(map[specifier], conditions)
  let best: { key: string; star: string } | null = null
  for (const key of Object.keys(map)) {
    const star = key.indexOf("*")
    if (star === -1 || key.indexOf("*", star + 1) !== -1) continue
    const prefix = key.slice(0, star)
    const suffix = key.slice(star + 1)
    if (!specifier.startsWith(prefix) || specifier.length < key.length) continue
    if (suffix !== "" && !specifier.endsWith(suffix)) continue
    if (best !== null && best.key.indexOf("*") >= prefix.length) continue
    best = { key, star: specifier.slice(prefix.length, specifier.length - suffix.length) }
  }
  if (best === null) return null
  const target = targetOf(map[best.key], conditions)
  return target === null ? null : target.replaceAll("*", best.star)
}

const PROBE = "__eskais_mockup_probe__"

// The folder an alias such as "#components/ui" stands for: the folder its files resolve into.
export function mappedDirectory(map: unknown, specifier: string, conditions: readonly string[]): string | null {
  const probed = matchMap(map, `${specifier}/${PROBE}`, conditions)
  if (probed?.includes(PROBE)) return probed.slice(0, probed.indexOf(PROBE)).replace(/\/$/, "")
  return matchMap(map, specifier, conditions)
}

// The prefixes an import has to start with to go through the map: "#components/" for "#components/*".
export function mapPrefixes(map: unknown): string[] {
  if (!isRecord(map)) return []
  return Object.keys(map).map((key) => (key.includes("*") ? key.slice(0, key.indexOf("*")) : key))
}

// The alias folders a map declares: "#components/*" → "#components", for a project without components.json.
export function mapAliases(map: unknown, conditions: readonly string[]): { specifier: string; target: string }[] {
  if (!isRecord(map)) return []
  const found: { specifier: string; target: string }[] = []
  for (const key of Object.keys(map)) {
    if (!key.endsWith("/*")) continue
    const specifier = key.slice(0, -2)
    const target = mappedDirectory(map, specifier, conditions)
    if (target !== null) found.push({ specifier, target })
  }
  return found
}

import { existsSync, readFileSync, readdirSync } from "node:fs"
import { basename, join, relative } from "node:path"
import { pathToFileURL } from "node:url"

import { importsOf, type Problem } from "./checks"
import { extractType, readExports } from "./inspect"
import { displayPath, EnvironmentError, toPosix } from "./project"

export type ProposedPart = {
  name: string
  file: string
  props: string[]
}

export type SdkPart = {
  part: string
  primitive: string
  reason: string
}

export type Gap = {
  component: string
  missing: string
  reason: string
}

export type MockupParts = {
  files: string[]
  proposed: ProposedPart[]
  sdkParts: SdkPart[]
  gaps: Gap[]
  problems: Problem[]
}

function kebab(name: string): string {
  return name
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1-$2")
    .toLowerCase()
}

function partFiles(mockup: string): string[] {
  const root = join(mockup, "parts")
  if (!existsSync(root)) return []
  const found: string[] = []
  const visit = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.name.startsWith(".")) continue
      const path = join(dir, entry.name)
      if (entry.isDirectory()) visit(path)
      else if (entry.name.endsWith(".tsx") && !/\.(test|spec)\./.test(entry.name)) found.push(path)
    }
  }
  visit(root)
  return found.toSorted()
}

function typeMembers(text: string): string[] {
  const open = text.indexOf("{")
  const end = text.lastIndexOf("}")
  if (open === -1 || end <= open) return []
  const body = text.slice(open + 1, end)
  const members: string[] = []
  let current = ""
  let depth = 0
  const flush = () => {
    const member = current.trim().replace(/[,;]$/, "").trim()
    if (member !== "" && !member.startsWith("//") && !member.startsWith("/*")) members.push(member)
    current = ""
  }
  for (const char of body) {
    if ("{[(".includes(char)) depth += 1
    if ("}])".includes(char)) depth -= 1
    if ((char === "\n" || char === ";") && depth === 0) {
      flush()
      continue
    }
    current += char
  }
  flush()
  return members
}

function sdkReason(source: string): string | null {
  const found = [...source.matchAll(/\/\/\s*sdk-reason:[ \t]*(.+)/g)]
  const reason = found.at(-1)?.[1]?.trim() ?? ""
  return reason === "" ? null : reason
}

function primaryPart(source: string, file: string): string | null {
  const values = readExports(source)
    .filter((entry) => entry.kind === "value")
    .map((entry) => entry.name)
    .filter((name) => /^[A-Z]/.test(name))
  if (values.length === 0) return null
  const name = kebab(basename(file).replace(/\.tsx$/, ""))
  return values.find((value) => kebab(value) === name) ?? values[0] ?? null
}

async function readGaps(mockup: string, cwd: string): Promise<Gap[]> {
  const file = join(mockup, "gaps.ts")
  if (!existsSync(file)) return []
  let module: Record<string, unknown>
  try {
    module = (await import(pathToFileURL(file).href)) as Record<string, unknown>
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    throw new EnvironmentError(`${displayPath(file, cwd)} could not be read: ${message}`)
  }
  const exported = module["gaps"] ?? module["default"]
  if (!Array.isArray(exported)) {
    throw new EnvironmentError(`${displayPath(file, cwd)} must export gaps: an array of { component, missing, reason }`)
  }
  return exported.map((entry, index) => {
    if (typeof entry !== "object" || entry === null) {
      throw new EnvironmentError(`${displayPath(file, cwd)}: gap ${index + 1} is not an object`)
    }
    const record = entry as Record<string, unknown>
    const component = record["component"]
    const missing = record["missing"]
    if (typeof component !== "string" || typeof missing !== "string") {
      throw new EnvironmentError(
        `${displayPath(file, cwd)}: gap ${index + 1} needs string component and missing fields`,
      )
    }
    const reason = record["reason"]
    return { component, missing, reason: typeof reason === "string" ? reason : "" }
  })
}

export async function readMockupParts(mockup: string, cwd: string): Promise<MockupParts> {
  const files = partFiles(mockup)
  const proposed: ProposedPart[] = []
  const sdkParts: SdkPart[] = []
  const problems: Problem[] = []
  for (const file of files) {
    const source = readFileSync(file, "utf8")
    const shown = toPosix(relative(mockup, file))
    for (const entry of readExports(source)) {
      if (entry.kind !== "value" || !/^[A-Z]/.test(entry.name)) continue
      const type = extractType(source, `${entry.name}Props`)
      if (type === null && !new RegExp(`\\bexport\\s+function\\s+${entry.name}\\b`).test(source)) continue
      proposed.push({
        name: entry.name,
        file: shown,
        props: type === null ? [] : typeMembers(type),
      })
    }
    const sdkImports = importsOf(source).filter(({ specifier }) => specifier.startsWith("@ui-sdk/"))
    if (sdkImports.length === 0) continue
    const part = primaryPart(source, file)
    const reason = sdkReason(source)
    if (part === null) {
      problems.push({
        file: toPosix(relative(cwd, file)),
        line: 1,
        column: 1,
        rule: "sdk-reason",
        message: "a part that uses a UI SDK primitive must export the component it builds",
      })
      continue
    }
    if (reason === null) {
      const first = sdkImports[0]
      problems.push({
        file: toPosix(relative(cwd, file)),
        line: first?.line ?? 1,
        column: first?.column ?? 1,
        rule: "sdk-reason",
        message: `add a line "// sdk-reason: <why Eskais cannot do this>" above the ${part} component`,
      })
      continue
    }
    for (const specifier of [...new Set(sdkImports.map((entry) => entry.specifier))].toSorted()) {
      sdkParts.push({ part, primitive: specifier, reason })
    }
  }
  return {
    files,
    proposed: proposed.toSorted(
      (left, right) => left.file.localeCompare(right.file) || left.name.localeCompare(right.name),
    ),
    sdkParts: sdkParts.toSorted(
      (left, right) => left.part.localeCompare(right.part) || left.primitive.localeCompare(right.primitive),
    ),
    gaps: await readGaps(mockup, cwd),
    problems,
  }
}

export function sdkDuplicateWarnings(sdkParts: SdkPart[], basenames: Set<string>): string[] {
  const warnings = new Set<string>()
  for (const { part, primitive } of sdkParts) {
    const name = primitive.split("/").at(-1) ?? primitive
    if (!basenames.has(name)) continue
    warnings.add(`${part} uses ${primitive}, but the project already installs a ${name} component; use it first`)
  }
  return [...warnings].toSorted()
}

import { existsSync, readFileSync, readdirSync, realpathSync, statSync } from "node:fs"
import { createRequire } from "node:module"
import { basename, dirname, isAbsolute, join, relative, resolve } from "node:path"

import { mapAliases, mappedDirectory, mapPrefixes, SOURCE_CONDITIONS } from "./package-map"
import { findWorkspace, packageRootOf, storePackages } from "./workspace"

export class EnvironmentError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "EnvironmentError"
  }
}

export type ProjectAlias = {
  name: string
  specifier: string
  dir: string | null
}

export type ConsumerRuntime = {
  tailwindNode: string
  tailwindOxide: string
  react: string
  reactServer: string
  tailwindPackage: string | null
  tailwindVersion: string
  reactVersion: string
}

export type PackageImports = {
  dir: string
  map: unknown
}

// Where the project's packages resolve from: its own folders first, then the stylesheet's package, the
// workspace root and every workspace package, then pnpm's and Bun's stores under the workspace roots.
export type Resolution = {
  bases: string[]
  stores: string[]
}

export type MockupProject = {
  root: string
  css: string
  tsconfig: string
  entry: string | null
  aliases: ProjectAlias[]
  pathPrefixes: string[]
  imports: PackageImports | null
  registries: Record<string, string>
  dependencies: Set<string>
  resolution: Resolution
  runtime: ConsumerRuntime
}

export type ProjectOptions = {
  cwd: string
  project?: string | undefined
  css?: string | undefined
  tsconfig?: string | undefined
  tailwind?: string | undefined
}

export type TsconfigPaths = {
  base: string
  entries: { pattern: string; target: string }[]
}

const JSONC = /("(?:\\[\s\S]|[^"\\])*")|\/\/[^\n]*|\/\*[\s\S]*?\*\/|,(\s*[}\]])/g

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

export function parseJsonc(text: string): unknown {
  return JSON.parse(text.replace(JSONC, (_match: string, quoted?: string, tail?: string) => quoted ?? tail ?? ""))
}

function readJsonc(path: string): unknown {
  return parseJsonc(readFileSync(path, "utf8"))
}

export function toPosix(path: string): string {
  return path.replaceAll("\\", "/")
}

export function displayPath(path: string, cwd: string): string {
  const shown = relative(cwd, path)
  return toPosix(shown === "" ? "." : shown)
}

function findUp(start: string, name: string): string | null {
  let current = resolve(start)
  for (;;) {
    const candidate = join(current, name)
    if (existsSync(candidate)) return candidate
    const parent = dirname(current)
    if (parent === current) return null
    current = parent
  }
}

function readComponents(path: string): {
  css: string | null
  aliases: Record<string, string>
  registries: Record<string, string>
} {
  const parsed = readJsonc(path)
  const document = isRecord(parsed) ? parsed : {}
  const tailwind = isRecord(document["tailwind"]) ? document["tailwind"] : {}
  const rawAliases = isRecord(document["aliases"]) ? document["aliases"] : {}
  const aliases: Record<string, string> = {}
  for (const [name, value] of Object.entries(rawAliases)) {
    if (typeof value === "string") aliases[name] = value
  }
  const rawRegistries = isRecord(document["registries"]) ? document["registries"] : {}
  const registries: Record<string, string> = {}
  for (const [name, value] of Object.entries(rawRegistries)) {
    if (typeof value === "string") registries[name] = value
  }
  const css = typeof tailwind["css"] === "string" ? tailwind["css"] : null
  return { css, aliases, registries }
}

function extendsOf(path: string): string | null {
  const parsed = readJsonc(path)
  const document = isRecord(parsed) ? parsed : {}
  const extended = document["extends"]
  if (typeof extended !== "string" || !extended.startsWith(".")) return null
  const candidate = resolve(dirname(path), extended)
  if (existsSync(candidate)) return candidate
  return existsSync(`${candidate}.json`) ? `${candidate}.json` : null
}

function setsJsx(tsconfig: string): boolean {
  const parsed = readJsonc(tsconfig)
  const compiler = isRecord(parsed) && isRecord(parsed["compilerOptions"]) ? parsed["compilerOptions"] : {}
  if (typeof compiler["jsx"] === "string") return true
  const parent = extendsOf(tsconfig)
  return parent !== null && setsJsx(parent)
}

// A root tsconfig.json that only lists references (Vite's template keeps the app's options in tsconfig.app.json)
// can't type-check a .tsx file on its own: use the referenced config that sets jsx, as tsc -b would.
export function checkTsconfig(tsconfig: string): string {
  const parsed = readJsonc(tsconfig)
  const references = isRecord(parsed) && Array.isArray(parsed["references"]) ? parsed["references"] : []
  if (references.length === 0 || setsJsx(tsconfig)) return tsconfig
  for (const reference of references) {
    if (!isRecord(reference) || typeof reference["path"] !== "string") continue
    const target = resolve(dirname(tsconfig), reference["path"])
    const file = existsSync(target) && statSync(target).isDirectory() ? join(target, "tsconfig.json") : target
    if (existsSync(file) && setsJsx(file)) return file
  }
  return tsconfig
}

export function readTsconfigPaths(tsconfig: string): TsconfigPaths {
  const parsed = readJsonc(tsconfig)
  const document = isRecord(parsed) ? parsed : {}
  const compiler = isRecord(document["compilerOptions"]) ? document["compilerOptions"] : {}
  const base =
    typeof compiler["baseUrl"] === "string" ? resolve(dirname(tsconfig), compiler["baseUrl"]) : dirname(tsconfig)
  const paths = isRecord(compiler["paths"]) ? compiler["paths"] : {}
  const entries: TsconfigPaths["entries"] = []
  for (const [pattern, targets] of Object.entries(paths)) {
    if (!Array.isArray(targets)) continue
    for (const target of targets) {
      if (typeof target === "string") entries.push({ pattern, target })
    }
  }
  if (entries.length > 0) return { base, entries }
  const parent = extendsOf(tsconfig)
  return parent === null ? { base, entries } : readTsconfigPaths(parent)
}

function directoryOrNull(path: string): string | null {
  return existsSync(path) && statSync(path).isDirectory() ? path : null
}

// Node's subpath imports (`"imports": { "#components/*": "./src/components/*" }`) in the project's package.json,
// which TypeScript and Bun read as aliases too.
export function readPackageImports(start: string): PackageImports | null {
  const dir = packageRootOf(start)
  if (dir === null) return null
  const parsed = readJsonc(join(dir, "package.json"))
  const map = isRecord(parsed) ? parsed["imports"] : undefined
  return isRecord(map) ? { dir, map } : null
}

function importsDirectory(specifier: string, imports: PackageImports | null): string | null {
  if (imports === null || !specifier.startsWith("#")) return null
  const target = mappedDirectory(imports.map, specifier, SOURCE_CONDITIONS)
  if (target === null || !target.startsWith(".")) return null
  return directoryOrNull(resolve(imports.dir, target))
}

function aliasDirectory(specifier: string, paths: TsconfigPaths, imports: PackageImports | null): string | null {
  return pathsDirectory(specifier, paths) ?? importsDirectory(specifier, imports)
}

function pathsDirectory(specifier: string, paths: TsconfigPaths): string | null {
  for (const { pattern, target } of paths.entries) {
    if (pattern.endsWith("/*")) {
      const prefix = pattern.slice(0, -1)
      if (!`${specifier}/`.startsWith(prefix)) continue
      const rest = specifier.slice(prefix.length - 1)
      const dir = resolve(paths.base, `${target.replace(/\/?\*$/, "")}/${rest}`)
      return existsSync(dir) ? dir : null
    }
    if (specifier === pattern) {
      const dir = resolve(paths.base, target)
      return existsSync(dir) ? dir : null
    }
  }
  return null
}

function aliasesFromPaths(paths: TsconfigPaths, imports: PackageImports | null): ProjectAlias[] {
  const aliases: ProjectAlias[] = []
  for (const { pattern, target } of paths.entries) {
    if (!pattern.endsWith("/*")) continue
    const specifier = pattern.slice(0, -2)
    if (aliases.some((alias) => alias.specifier === specifier)) continue
    const dir = resolve(paths.base, target.replace(/\/?\*$/, ""))
    aliases.push({ name: specifier, specifier, dir: directoryOrNull(dir) })
  }
  for (const { specifier, target } of imports === null ? [] : mapAliases(imports.map, SOURCE_CONDITIONS)) {
    if (aliases.some((alias) => alias.specifier === specifier) || !target.startsWith(".")) continue
    aliases.push({ name: specifier, specifier, dir: directoryOrNull(resolve(imports?.dir ?? "", target)) })
  }
  return aliases
}

function readAliases(
  declared: Record<string, string>,
  paths: TsconfigPaths,
  imports: PackageImports | null,
): ProjectAlias[] {
  const aliases = Object.entries(declared).map(([name, specifier]) => ({
    name,
    specifier,
    dir: aliasDirectory(specifier, paths, imports),
  }))
  for (const alias of aliases) {
    if (alias.dir !== null && !statSync(alias.dir).isDirectory()) alias.dir = null
  }
  return aliases
}

function findEntry(root: string, css: string): string | null {
  const cssDir = dirname(css)
  const candidates = [
    join(cssDir, "main.tsx"),
    join(cssDir, "index.tsx"),
    join(cssDir, "App.tsx"),
    join(cssDir, "app.tsx"),
    join(root, "src", "main.tsx"),
    join(root, "src", "index.tsx"),
    join(root, "src", "App.tsx"),
    join(root, "app", "page.tsx"),
  ]
  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate
  }
  const html = join(root, "index.html")
  if (existsSync(html)) {
    const script = readFileSync(html, "utf8").match(/<script[^>]+src=["']([^"']+)["']/i)
    if (script?.[1] !== undefined) {
      const resolved = resolve(root, script[1])
      if (existsSync(resolved)) return resolved
    }
  }
  return null
}

function readDependencies(root: string): Set<string> {
  const names = new Set<string>()
  const path = join(root, "package.json")
  if (!existsSync(path)) return names
  const parsed = readJsonc(path)
  const document = isRecord(parsed) ? parsed : {}
  for (const key of ["dependencies", "devDependencies", "peerDependencies", "optionalDependencies"]) {
    const field = document[key]
    if (!isRecord(field)) continue
    for (const name of Object.keys(field)) names.add(name)
  }
  return names
}

function packageDirectory(base: string, specifier: string): string | null {
  const require = createRequire(join(base, "package.json"))
  try {
    return dirname(realpathSync(require.resolve(`${specifier}/package.json`)))
  } catch {
    return packageDirectoryOfEntry(require, specifier)
  }
}

// Some packages don't export their package.json, so the entry's directory is walked up to the first manifest.
function packageDirectoryOfEntry(require: NodeRequire, specifier: string): string | null {
  let current: string
  try {
    current = dirname(realpathSync(require.resolve(specifier)))
  } catch {
    return null
  }
  for (;;) {
    if (existsSync(join(current, "package.json"))) return current
    const parent = dirname(current)
    if (parent === current) return null
    current = parent
  }
}

function packageEntry(base: string, specifier: string): string | null {
  const require = createRequire(join(base, "package.json"))
  try {
    return require.resolve(specifier)
  } catch {
    return null
  }
}

function throughTailwindPlugin(base: string, specifier: string): string | null {
  for (const plugin of ["@tailwindcss/vite", "@tailwindcss/postcss"]) {
    const pluginDir = packageDirectory(base, plugin)
    if (pluginDir === null) continue
    const found = packageDirectory(pluginDir, specifier)
    if (found !== null) return found
  }
  return null
}

function firstPresent<T>(bases: string[], find: (base: string) => T | null): T | null {
  for (const base of bases) {
    const found = find(base)
    if (found !== null) return found
  }
  return null
}

function readVersion(directory: string): string {
  const parsed = readJsonc(join(directory, "package.json"))
  const document = isRecord(parsed) ? parsed : {}
  return typeof document["version"] === "string" ? document["version"] : "unknown"
}

export type LocatedPackage = {
  dir: string
  from: string
}

// A package's folder, and a folder that resolves it and its own dependencies, from the first base or store that has it.
export function locatePackage(resolution: Resolution, name: string): LocatedPackage | null {
  for (const base of resolution.bases) {
    const dir = packageDirectory(base, name)
    if (dir !== null) return { dir, from: base }
  }
  for (const store of resolution.stores) {
    const entry = storePackages(store, name)[0]
    if (entry !== undefined) return { dir: entry.dir, from: entry.from }
  }
  return null
}

function locatedDirectory(resolution: Resolution, name: string): string | null {
  return locatePackage(resolution, name)?.dir ?? null
}

function locatedEntry(resolution: Resolution, name: string): string | null {
  const located = locatePackage(resolution, name)
  return located === null ? null : packageEntry(located.from, name)
}

function resolveTailwind(resolution: Resolution, root: string, forced: string | null) {
  const bases = forced === null ? resolution.bases : [forced]
  const scoped: Resolution = forced === null ? resolution : { bases, stores: [] }
  const tailwindNode =
    locatedDirectory(scoped, "@tailwindcss/node") ??
    firstPresent(bases, (base) => throughTailwindPlugin(base, "@tailwindcss/node"))
  const tailwindOxide =
    (tailwindNode === null ? null : packageDirectory(tailwindNode, "@tailwindcss/oxide")) ??
    locatedDirectory(scoped, "@tailwindcss/oxide") ??
    firstPresent(bases, (base) => throughTailwindPlugin(base, "@tailwindcss/oxide"))
  if (tailwindNode === null || tailwindOxide === null) {
    throw new EnvironmentError(
      forced === null
        ? `Tailwind is not installed for ${root} or its workspace: add tailwindcss (with @tailwindcss/node and @tailwindcss/oxide) or @tailwindcss/vite to the project, or pass --tailwind <dir> with the folder of a package that has it.`
        : `--tailwind ${forced}: @tailwindcss/node and @tailwindcss/oxide do not resolve from it; pass the folder of a package that depends on tailwindcss and @tailwindcss/vite or @tailwindcss/postcss.`,
    )
  }
  const tailwindPackage =
    (forced === null ? null : packageDirectory(forced, "tailwindcss")) ??
    packageDirectory(tailwindNode, "tailwindcss") ??
    locatedDirectory(scoped, "tailwindcss")
  return { tailwindNode, tailwindOxide, tailwindPackage }
}

function resolveRuntime(resolution: Resolution, root: string, forcedTailwind: string | null): ConsumerRuntime {
  const { tailwindNode, tailwindOxide, tailwindPackage } = resolveTailwind(resolution, root, forcedTailwind)
  const reactDir = locatedDirectory(resolution, "react")
  const reactDomDir = locatedDirectory(resolution, "react-dom")
  const reactEntry = locatedEntry(resolution, "react")
  if (reactDir === null || reactDomDir === null || reactEntry === null) {
    throw new EnvironmentError(`React is not installed for ${root}: add react and react-dom to the project.`)
  }
  const reactServer = packageEntry(reactDomDir, "react-dom/server") ?? locatedEntry(resolution, "react-dom/server")
  if (reactServer === null) throw new EnvironmentError(`react-dom/server does not resolve from ${reactDomDir}`)
  return {
    tailwindNode: packageEntry(tailwindNode, "@tailwindcss/node") ?? join(tailwindNode, "dist", "index.mjs"),
    tailwindOxide: packageEntry(tailwindOxide, "@tailwindcss/oxide") ?? join(tailwindOxide, "index.js"),
    react: reactEntry,
    reactServer,
    tailwindPackage,
    tailwindVersion: tailwindPackage === null ? readVersion(tailwindNode) : readVersion(tailwindPackage),
    reactVersion: readVersion(reactDir),
  }
}

export function projectResolution(root: string, css: string, entry: string | null): Resolution {
  const cssPackage = packageRootOf(css)
  const workspaces = [findWorkspace(root), cssPackage === null ? null : findWorkspace(cssPackage)].filter(
    (workspace) => workspace !== null,
  )
  const bases = [root, dirname(css)]
  if (cssPackage !== null) bases.push(cssPackage)
  if (entry !== null) bases.push(dirname(entry))
  for (const workspace of workspaces) bases.push(workspace.root, ...workspace.packages)
  const stores = [root, ...workspaces.map((workspace) => workspace.root)]
  return { bases: [...new Set(bases)], stores: [...new Set(stores)] }
}

function forcedTailwindDirectory(cwd: string, value: string | undefined): string | null {
  if (value === undefined) return null
  const dir = resolve(cwd, value)
  if (!existsSync(dir) || !statSync(dir).isDirectory()) throw new EnvironmentError(`--tailwind ${dir} is not a folder`)
  return basename(dir) === "node_modules" ? dirname(dir) : dir
}

function projectTsconfig(options: ProjectOptions, root: string, css: string): string {
  if (options.tsconfig !== undefined) {
    const file = resolve(options.cwd, options.tsconfig)
    if (!existsSync(file)) throw new EnvironmentError(`--tsconfig ${file} does not exist`)
    return statSync(file).isDirectory() ? join(file, "tsconfig.json") : file
  }
  // The project's own tsconfig, not the one of the app whose stylesheet --css names: that one may carry the
  // app's ambient types (vite/client) and other aliases.
  const tsconfig = findUp(root, "tsconfig.json") ?? findUp(dirname(css), "tsconfig.json")
  if (tsconfig === null) {
    throw new EnvironmentError(
      `no tsconfig.json above ${root}; the mockup reads the project's aliases from it (or pass --tsconfig <file>)`,
    )
  }
  return tsconfig
}

export function findProject(options: ProjectOptions): MockupProject {
  const start = options.project === undefined ? resolve(options.cwd) : resolve(options.cwd, options.project)
  const componentsFile =
    options.project === undefined
      ? findUp(start, "components.json")
      : existsSync(join(start, "components.json"))
        ? join(start, "components.json")
        : null
  if (componentsFile === null && options.css === undefined) {
    throw new EnvironmentError(`no components.json in ${start} or above it; pass --project <dir> or --css <stylesheet>`)
  }
  const root = componentsFile === null ? start : dirname(componentsFile)
  const components =
    componentsFile === null ? { css: null, aliases: {}, registries: {} } : readComponents(componentsFile)
  const css =
    options.css === undefined
      ? components.css === null
        ? null
        : resolve(root, components.css)
      : resolve(options.cwd, options.css)
  if (css === null) throw new EnvironmentError(`${componentsFile} has no tailwind.css; pass --css <stylesheet>`)
  if (!existsSync(css)) throw new EnvironmentError(`the stylesheet ${css} does not exist`)

  const tsconfig = projectTsconfig(options, root, css)
  const paths = readTsconfigPaths(tsconfig)
  const imports = readPackageImports(root)
  const aliases =
    componentsFile === null ? aliasesFromPaths(paths, imports) : readAliases(components.aliases, paths, imports)
  const pathPrefixes = [
    ...new Set([
      ...paths.entries.map(({ pattern }) => (pattern.endsWith("/*") ? pattern.slice(0, -1) : pattern)),
      ...(imports === null ? [] : mapPrefixes(imports.map)),
    ]),
  ]
  const entry = findEntry(root, css)
  const resolution = projectResolution(root, css, entry)
  return {
    root,
    css,
    tsconfig,
    entry,
    aliases,
    pathPrefixes,
    imports,
    registries: components.registries,
    dependencies: readDependencies(root),
    resolution,
    runtime: resolveRuntime(resolution, root, forcedTailwindDirectory(options.cwd, options.tailwind)),
  }
}

export function mockupDirectory(project: MockupProject, name: string): string {
  return join(project.root, ".mockups", name)
}

export function aliasOf(project: MockupProject, file: string): ProjectAlias | null {
  for (const alias of project.aliases) {
    if (alias.dir === null) continue
    const shown = relative(alias.dir, file)
    if (shown.startsWith("..") || isAbsolute(shown)) continue
    return alias
  }
  return null
}

export function specifierOf(project: MockupProject, file: string): string | null {
  const alias = aliasOf(project, file)
  if (alias === null || alias.dir === null) return null
  const shown = toPosix(relative(alias.dir, file)).replace(/\.(tsx|ts|jsx|js)$/, "")
  return `${alias.specifier}/${shown}`
}

export function packageDirectoryOf(root: string, specifier: string): string | null {
  return packageDirectory(root, specifier)
}

const SKIPPED_DIRECTORIES = new Set(["node_modules", ".mockups", ".git", "dist", "build", "coverage", ".next"])

function pathRoots(project: MockupProject): string[] {
  const paths = readTsconfigPaths(project.tsconfig)
  const roots = new Set<string>()
  for (const { target } of paths.entries) {
    const star = target.indexOf("*")
    const fixed = star === -1 ? target : target.slice(0, star)
    const root = resolve(paths.base, fixed)
    if (existsSync(root)) roots.add(root)
  }
  const imports = project.imports
  for (const { target } of imports === null ? [] : mapAliases(imports.map, SOURCE_CONDITIONS)) {
    const root = resolve(imports?.dir ?? project.root, target)
    if (target.startsWith(".") && existsSync(root)) roots.add(root)
  }
  for (const alias of project.aliases) if (alias.dir !== null) roots.add(alias.dir)
  return [...roots]
}

function sourceFile(path: string): boolean {
  if (!/\.(tsx?|jsx?)$/.test(path)) return false
  if (/\.(test|spec)\./.test(path) || path.endsWith(".d.ts")) return false
  return true
}

function walkSources(root: string, found: Set<string>, depth: number) {
  if (depth > 12 || !existsSync(root)) return
  const stats = statSync(root)
  if (!stats.isDirectory()) {
    if (sourceFile(root)) found.add(root)
    return
  }
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    if (entry.name.startsWith(".") || SKIPPED_DIRECTORIES.has(entry.name)) continue
    const path = join(root, entry.name)
    if (entry.isDirectory()) walkSources(path, found, depth + 1)
    else if (sourceFile(path)) found.add(path)
  }
}

export function projectSourceFiles(project: MockupProject): string[] {
  const found = new Set<string>()
  for (const root of pathRoots(project)) walkSources(root, found, 0)
  return [...found].toSorted()
}

export function sourceBasenames(files: string[]): Set<string> {
  return new Set(
    files.map(
      (file) =>
        toPosix(file)
          .split("/")
          .at(-1)
          ?.replace(/\.(tsx|ts|jsx|js)$/, "") ?? "",
    ),
  )
}

import { createHash } from "node:crypto"
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { basename, dirname, isAbsolute, join, relative, resolve } from "node:path"
import { fileURLToPath } from "node:url"

import { importsOf } from "./checks"
import {
  checkTsconfig,
  displayPath,
  EnvironmentError,
  projectSourceFiles,
  readTsconfigPaths,
  sourceBasenames,
  specifierOf,
  toPosix,
  type MockupProject,
} from "./project"

export type RegistryItemFile = {
  path: string
  type?: string
  content?: string
}

export type RegistryItem = {
  name: string
  type?: string
  description?: string
  dependencies?: string[]
  registryDependencies?: string[]
  files?: RegistryItemFile[]
}

export type RegistryIndex = {
  items: RegistryItem[]
}

export type RegistrySource = {
  key: string
  template: string
  ref: string
  dir: string
  index: RegistryIndex
}

export type InstallEntry = {
  item: string
  command: string
}

type LoadedItem = {
  item: RegistryItem
  source: RegistrySource
  files: Map<string, string>
}

type RegistryLoad = {
  sources: RegistrySource[]
  items: Map<string, LoadedItem>
  cache: Map<string, LoadedItem>
}

export type PreparedRegistry = {
  install: InstallEntry[]
  cacheDirs: string[]
}

const FETCH_TIMEOUT = 20_000
const SOURCE_FILE = /\.(tsx|ts)$/

function parseDocument(text: string, label: string): unknown {
  try {
    return JSON.parse(text)
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    throw new EnvironmentError(`${label} is not JSON: ${message}`)
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function asItem(value: unknown, label: string): RegistryItem {
  if (!isRecord(value) || typeof value["name"] !== "string") {
    throw new EnvironmentError(`${label} does not describe a registry item`)
  }
  return value as RegistryItem
}

function asIndex(value: unknown, label: string): RegistryIndex {
  if (!isRecord(value) || !Array.isArray(value["items"])) {
    throw new EnvironmentError(`${label} does not describe a registry index`)
  }
  return { items: value["items"].map((item) => asItem(item, label)) }
}

function registryRef(template: string): string {
  const commit = /\/([0-9a-f]{40})\//.exec(template)?.[1]
  return commit ?? createHash("sha1").update(template).digest("hex").slice(0, 12)
}

async function readRegistryText(project: MockupProject, template: string, name: string): Promise<string> {
  const href = template.replaceAll("{name}", name)
  if (/^https?:\/\//.test(href)) {
    let response: Response
    try {
      response = await fetch(href, { signal: AbortSignal.timeout(FETCH_TIMEOUT) })
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      throw new EnvironmentError(
        `could not reach the registry at ${href} (${message}); the cache under .mockups/.registry is reused when this succeeds once`,
      )
    }
    if (!response.ok) throw new EnvironmentError(`the registry at ${href} answered ${response.status}`)
    return await response.text()
  }
  const path = href.startsWith("file:") ? fileURLToPath(href) : isAbsolute(href) ? href : resolve(project.root, href)
  if (!existsSync(path)) throw new EnvironmentError(`the registry file ${path} does not exist`)
  return readFileSync(path, "utf8")
}

async function loadSource(project: MockupProject, key: string, template: string): Promise<RegistrySource> {
  if (!template.includes("{name}")) {
    throw new EnvironmentError(`the ${key} registry URL needs a {name} placeholder: ${template}`)
  }
  const ref = registryRef(template)
  const dir = join(project.root, ".mockups", ".registry", ref)
  const cached = join(dir, "registry.json")
  let text: string
  if (existsSync(cached)) {
    text = readFileSync(cached, "utf8")
  } else {
    text = await readRegistryText(project, template, "registry")
    mkdirSync(dir, { recursive: true })
    writeFileSync(cached, text)
  }
  return { key, template, ref, dir, index: asIndex(parseDocument(text, cached), cached) }
}

async function loadSources(project: MockupProject): Promise<RegistrySource[]> {
  const entries = Object.entries(project.registries)
  if (entries.length === 0) {
    throw new EnvironmentError(
      'components.json has no registries entry; add one, for example "registries": { "@eskais": "https://raw.githubusercontent.com/p-otero/eskais-ui/refs/tags/<tag>/public/r/{name}.json" }',
    )
  }
  return Promise.all(entries.map(([key, template]) => loadSource(project, key, template)))
}

function sourceBase(path: string): string {
  return basename(path).replace(/\.(tsx|ts)$/, "")
}

async function loadItem(project: MockupProject, load: RegistryLoad, name: string): Promise<LoadedItem> {
  const cached = load.cache.get(name)
  if (cached !== undefined) return cached
  const source = load.sources.find((candidate) => candidate.index.items.some((item) => item.name === name))
  if (source === undefined) {
    const known = load.sources.flatMap((candidate) => candidate.index.items.map((item) => item.name)).toSorted()
    throw new EnvironmentError(
      `no configured registry has the item "${name}"; available: ${known.slice(0, 12).join(", ")}${known.length > 12 ? ", …" : ""}`,
    )
  }
  const path = join(source.dir, "items", `${name}.json`)
  let text: string
  if (existsSync(path)) {
    text = readFileSync(path, "utf8")
  } else {
    text = await readRegistryText(project, source.template, name)
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, text)
  }
  const item = asItem(parseDocument(text, path), path)
  if (item.name !== name) throw new EnvironmentError(`${path} describes the item "${item.name}", not "${name}"`)
  const files = new Map<string, string>()
  for (const file of item.files ?? []) {
    if (typeof file.content !== "string") continue
    files.set(sourceBase(file.path), file.path)
  }
  const loaded: LoadedItem = { item, source, files }
  load.cache.set(name, loaded)
  return loaded
}

function dependencyName(specifier: string): string {
  return specifier.split("/").at(-1) ?? specifier
}

async function ensureItem(
  project: MockupProject,
  load: RegistryLoad,
  name: string,
  installed: Set<string>,
  visiting: Set<string>,
  force: boolean,
): Promise<void> {
  if (load.items.has(name) || (!force && installed.has(name)) || visiting.has(name)) return
  visiting.add(name)
  const loaded = await loadItem(project, load, name)
  if (loaded.files.size === 0) {
    visiting.delete(name)
    return
  }
  for (const dependency of loaded.item.registryDependencies ?? []) {
    // oxlint-disable-next-line no-await-in-loop -- the recursion shares one cache and visiting set
    await ensureItem(project, load, dependencyName(dependency), installed, visiting, false)
  }
  visiting.delete(name)
  load.items.set(name, loaded)
}

export type ShippedFile = {
  item: string
  path: string
  content: string
  dir: string
}

// `shadcn add` overwrites a file that two items ship, so the cache accepts it when every
// copy is byte-identical. Line endings are not normalised: shadcn writes a CRLF copy as is.
export function shippedFiles(items: Iterable<{ item: RegistryItem; dir: string }>): Map<string, ShippedFile> {
  const shipped = new Map<string, ShippedFile>()
  for (const { item, dir } of items) {
    for (const file of item.files ?? []) {
      if (typeof file.content !== "string") continue
      const base = sourceBase(file.path)
      const first = shipped.get(base)
      if (first === undefined) {
        shipped.set(base, { item: item.name, path: file.path, content: file.content, dir })
        continue
      }
      if (first.content !== file.content || basename(first.path) !== basename(file.path)) {
        throw new EnvironmentError(
          `the items ${first.item} and ${item.name} both ship ${base} (${first.path} and ${file.path}) with different contents; install one of them, or a registry version where they share it`,
        )
      }
    }
  }
  return shipped
}

function writeFiles(load: RegistryLoad): Map<string, string> {
  const shipped = shippedFiles([...load.items.values()].map(({ item, source }) => ({ item, dir: source.dir })))
  const files = new Map<string, string>()
  for (const [base, file] of shipped) {
    const target = join(file.dir, "files", basename(file.path))
    mkdirSync(dirname(target), { recursive: true })
    writeFileSync(target, file.content)
    files.set(base, target)
  }
  return files
}

// A fetched item imports `@/…`, as the registry ships it: a sibling in the cache becomes a relative path, and an
// installed file the project's own specifier when `@/` isn't one of its aliases (a project on `#components/*`).
function rewriteCachedImports(
  project: MockupProject,
  files: Map<string, string>,
  installed: Map<string, string | null>,
) {
  const keepsAt = project.pathPrefixes.some((prefix) => prefix.startsWith("@/"))
  for (const file of files.values()) {
    const source = readFileSync(file, "utf8")
    const rewritten = source.replaceAll(/(["'])@\/([^"'\n]+)\1/g, (match: string, quote: string, path: string) => {
      const base = basename(path).replace(/\.(tsx|ts)$/, "")
      if (base === "") return match
      const own = installed.get(base)
      if (own !== undefined) return keepsAt || own === null ? match : `${quote}${own}${quote}`
      const target = files.get(base)
      if (target === undefined) return match
      const shown = toPosix(relative(dirname(file), target)).replace(/\.(tsx|ts)$/, "")
      return `${quote}${shown.startsWith(".") ? shown : `./${shown}`}${quote}`
    })
    if (rewritten !== source) writeFileSync(file, rewritten)
  }
}

function installedSpecifiers(project: MockupProject, files: string[]): Map<string, string | null> {
  const found = new Map<string, string | null>()
  for (const file of files) {
    const base = basename(file).replace(/\.(tsx|ts|jsx|js)$/, "")
    if (!found.has(base) || found.get(base) === null) found.set(base, specifierOf(project, file))
  }
  return found
}

function packageName(specifier: string): string {
  if (specifier.startsWith("@")) {
    const [scope = "", rest = ""] = specifier.split("/")
    return `${scope}/${rest.split("@")[0] ?? ""}`
  }
  return specifier.split("@")[0] ?? specifier
}

function missingDependencies(project: MockupProject, load: RegistryLoad): string[] {
  const missing = new Set<string>()
  for (const { item } of load.items.values()) {
    for (const dependency of item.dependencies ?? []) {
      const name = packageName(dependency)
      if (!project.dependencies.has(name)) missing.add(name)
    }
  }
  return [...missing].toSorted()
}

function relativeFrom(from: string, path: string): string {
  const shown = toPosix(relative(from, path))
  return shown.startsWith(".") ? shown : `./${shown}`
}

export function mockupTsconfigPath(mockup: string): string {
  return join(mockup, "tsconfig.json")
}

function writeMockupTsconfig(project: MockupProject, mockup: string, cacheDirs: string[]) {
  const target = mockupTsconfigPath(mockup)
  if (cacheDirs.length === 0) {
    rmSync(target, { force: true })
    return
  }
  const paths = readTsconfigPaths(project.tsconfig)
  const from = dirname(target)
  const mapped: Record<string, string[]> = {}
  for (const entry of paths.entries) {
    const absolute = resolve(paths.base, entry.target)
    mapped[entry.pattern] ??= []
    mapped[entry.pattern]?.push(relativeFrom(from, absolute))
  }
  mapped["@registry/*"] = cacheDirs.map((dir) => relativeFrom(from, join(dir, "*")))
  const document = {
    extends: relativeFrom(from, checkTsconfig(project.tsconfig)),
    compilerOptions: { paths: mapped },
  }
  writeFileSync(target, `${JSON.stringify(document, null, 2)}\n`)
}

export async function prepareRegistry(
  project: MockupProject,
  mockup: string,
  files: string[],
): Promise<PreparedRegistry> {
  const wanted = new Set(
    files.flatMap((file) =>
      importsOf(readFileSync(file, "utf8"))
        .map(({ specifier }) => specifier)
        .filter((specifier) => specifier.startsWith("@registry/"))
        .map((specifier) => specifier.slice("@registry/".length)),
    ),
  )
  if (wanted.size === 0) {
    writeMockupTsconfig(project, mockup, [])
    return { install: [], cacheDirs: [] }
  }
  const sources = await loadSources(project)
  const load: RegistryLoad = { sources, items: new Map(), cache: new Map() }
  const ownFiles = projectSourceFiles(project)
  const installed = sourceBasenames(ownFiles)
  // oxlint-disable-next-line no-await-in-loop -- each fetch fills the same cache and dependency chain
  for (const name of [...wanted].toSorted()) await ensureItem(project, load, name, installed, new Set(), true)
  const filesByBase = writeFiles(load)
  rewriteCachedImports(project, filesByBase, installedSpecifiers(project, ownFiles))
  const missing = missingDependencies(project, load)
  if (missing.length > 0) {
    throw new EnvironmentError(
      `the fetched registry items need npm packages the project does not declare: ${missing.join(", ")}\ninstall them in ${project.root} (bun add ${missing.join(" ")} or npm install ${missing.join(" ")}) and build again`,
    )
  }
  const install = [...load.items.values()]
    .map(({ item, source }) => ({
      item: item.name,
      command: `npx shadcn@latest add ${source.key}/${item.name}`,
    }))
    .toSorted((left, right) => left.item.localeCompare(right.item))
  const cacheDirs = [...new Set([...load.items.values()].map(({ source }) => join(source.dir, "files")))].toSorted()
  writeMockupTsconfig(project, mockup, cacheDirs)
  return { install, cacheDirs }
}

function componentItem(item: RegistryItem): boolean {
  return (item.files ?? []).some((file) => SOURCE_FILE.test(file.path))
}

function installedItem(item: RegistryItem, basenames: Set<string>): boolean {
  const shipped = (item.files ?? []).filter((file) => SOURCE_FILE.test(file.path))
  return shipped.every((file) => basenames.has(basename(file.path).replace(SOURCE_FILE, "")))
}

function oneLine(description: string | undefined): string {
  if (description === undefined) return ""
  const text = description.replaceAll(/\s+/g, " ").trim()
  const sentence = /^(.+?[.!?])(\s|$)/.exec(text)?.[1] ?? text
  return sentence.length > 110 ? `${sentence.slice(0, 109)}…` : sentence
}

export async function registryMissing(
  project: MockupProject,
): Promise<{ source: RegistrySource; items: RegistryItem[]; total: number }[]> {
  const sources = await loadSources(project)
  const basenames = sourceBasenames(projectSourceFiles(project))
  return sources.map((source) => {
    const components = source.index.items.filter(componentItem)
    return {
      source,
      total: components.length,
      items: components
        .filter((item) => !installedItem(item, basenames))
        .toSorted((a, b) => a.name.localeCompare(b.name)),
    }
  })
}

export async function registryListText(project: MockupProject, cwd: string): Promise<string> {
  const missing = await registryMissing(project)
  const lines: string[] = []
  for (const { source, items, total } of missing) {
    lines.push(
      `${source.key} ${source.ref}  ${items.length} of ${total} component items not installed  (${displayPath(source.dir, cwd)})`,
    )
    for (const item of items) lines.push(`  ${item.name.padEnd(24)} ${oneLine(item.description)}`.trimEnd())
  }
  return lines.join("\n")
}

export async function registryListJson(project: MockupProject, cwd: string) {
  const missing = await registryMissing(project)
  return missing.map(({ source, items, total }) => ({
    registry: source.key,
    ref: source.ref,
    cache: displayPath(source.dir, cwd),
    total,
    items: items.map((item) => ({
      name: item.name,
      type: item.type ?? null,
      description: oneLine(item.description),
    })),
  }))
}

import { existsSync, readFileSync } from "node:fs"
import { join } from "node:path"

import { extractType, readExports } from "./inspect"
import { displayPath, EnvironmentError, packageDirectoryOf, type MockupProject } from "./project"

export type SdkSubpath = {
  name: string
  specifier: string
  types: string
  parts: string[]
  props: { name: string; text: string }[]
}

export type SdkPackage = {
  name: string
  version: string
  dir: string
  subpaths: SdkSubpath[]
}

type PackageDocument = {
  version?: string
  exports?: unknown
}

function packageDocument(dir: string): PackageDocument {
  const path = join(dir, "package.json")
  if (!existsSync(path)) throw new EnvironmentError(`${dir} has no package.json`)
  return JSON.parse(readFileSync(path, "utf8")) as PackageDocument
}

function exportsMap(document: PackageDocument): Record<string, unknown> {
  const exported = document.exports
  if (typeof exported === "string") return { ".": exported }
  return typeof exported === "object" && exported !== null ? (exported as Record<string, unknown>) : {}
}

function typeEntry(entry: unknown): string | null {
  if (typeof entry === "string") return entry
  if (typeof entry !== "object" || entry === null) return null
  const record = entry as Record<string, unknown>
  for (const key of ["types", "default", "import"]) {
    const value = record[key]
    if (typeof value === "string") return value
  }
  return null
}

function propsOf(source: string, parts: string[]): { name: string; text: string }[] {
  const types = readExports(source)
    .filter((entry) => entry.kind === "type" && entry.name.endsWith("Props"))
    .map((entry) => entry.name)
  const preferred = types.toSorted((left, right) => {
    const leftMain = parts.some((part) => `${part}Props` === left) ? 0 : 1
    const rightMain = parts.some((part) => `${part}Props` === right) ? 0 : 1
    return leftMain - rightMain || left.localeCompare(right)
  })
  const found: { name: string; text: string }[] = []
  for (const name of preferred) {
    const text = extractType(source, name)
    if (text !== null) found.push({ name, text })
  }
  return found
}

function readPackage(project: MockupProject, name: string): SdkPackage | null {
  const dir = packageDirectoryOf(project.root, name)
  if (dir === null) return null
  const document = packageDocument(dir)
  const subpaths: SdkSubpath[] = []
  for (const [key, entry] of Object.entries(exportsMap(document))) {
    if (!key.startsWith("./") || key === "./package.json") continue
    const relativeTypes = typeEntry(entry)
    if (relativeTypes === null) continue
    const types = join(dir, relativeTypes)
    if (!existsSync(types)) continue
    const source = readFileSync(types, "utf8")
    const parts = readExports(source)
      .filter((exported) => exported.kind === "value" && /^[A-Z]/.test(exported.name))
      .map((exported) => exported.name)
    subpaths.push({
      name: key.slice(2),
      specifier: `${name}/${key.slice(2)}`,
      types,
      parts,
      props: propsOf(source, parts),
    })
  }
  return {
    name,
    version: typeof document.version === "string" ? document.version : "unknown",
    dir,
    subpaths: subpaths.toSorted((left, right) => left.name.localeCompare(right.name)),
  }
}

export function installedSdkPackages(project: MockupProject): SdkPackage[] {
  return [...project.dependencies]
    .filter((name) => name.startsWith("@ui-sdk/"))
    .toSorted((left, right) =>
      left === "@ui-sdk/react" ? -1 : right === "@ui-sdk/react" ? 1 : left.localeCompare(right),
    )
    .map((name) => readPackage(project, name))
    .filter((entry): entry is SdkPackage => entry !== null && entry.subpaths.length > 0)
}

export function sdkPublicSpecifiers(project: MockupProject): Set<string> {
  return new Set(installedSdkPackages(project).flatMap((entry) => entry.subpaths.map((subpath) => subpath.specifier)))
}

function preview(parts: string[]): string {
  if (parts.length === 0) return ""
  return parts.length > 4 ? `${parts.slice(0, 4).join(", ")}, …` : parts.join(", ")
}

export function sdkIndexText(project: MockupProject, cwd: string): string {
  const packages = installedSdkPackages(project)
  if (packages.length === 0) {
    throw new EnvironmentError(
      `no @ui-sdk package is installed in ${displayPath(project.root, cwd)}; add @ui-sdk/react and @ui-sdk/core`,
    )
  }
  const lines: string[] = []
  for (const entry of packages) {
    if (entry.name !== "@ui-sdk/react") {
      lines.push(`${entry.name} ${entry.version}  ${entry.subpaths.length} public subpaths (behaviour)`)
      continue
    }
    lines.push(`${entry.name} ${entry.version}  ${entry.subpaths.length} public subpaths`)
    for (const subpath of entry.subpaths) {
      lines.push(`  ${subpath.name.padEnd(20)} ${preview(subpath.parts)}`.trimEnd())
    }
  }
  return lines.join("\n")
}

export function sdkIndexJson(project: MockupProject) {
  return installedSdkPackages(project).map((entry) => ({
    package: entry.name,
    version: entry.version,
    subpaths: entry.subpaths.map((subpath) => ({
      name: subpath.name,
      specifier: subpath.specifier,
      parts: subpath.parts,
    })),
  }))
}

export type SdkDetail = SdkSubpath & { package: string; version: string }

export function sdkDetail(project: MockupProject, name: string): SdkDetail {
  const packages = installedSdkPackages(project)
  const packagesInOrder = packages.toSorted((left, right) =>
    left.name === "@ui-sdk/react" ? -1 : right.name === "@ui-sdk/react" ? 1 : left.name.localeCompare(right.name),
  )
  const wanted = name.startsWith("@") ? name : null
  for (const entry of packagesInOrder) {
    const subpath =
      wanted === null
        ? entry.subpaths.find((candidate) => candidate.name === name)
        : entry.subpaths.find((candidate) => candidate.specifier === wanted)
    if (subpath !== undefined) return { ...subpath, package: entry.name, version: entry.version }
  }
  throw new EnvironmentError(`no installed @ui-sdk package exports "${name}"; inspect --sdk lists the public subpaths`)
}

export function sdkDetailText(detail: SdkDetail, cwd: string): string {
  const lines = [
    `${detail.specifier}  (${displayPath(detail.types, cwd)})`,
    `import { ${detail.parts.join(", ")} } from "${detail.specifier}"`,
    `parts ${detail.parts.join(", ")}`,
  ]
  for (const props of detail.props.slice(0, 3)) lines.push(props.text)
  if (detail.props.length > 3) lines.push(`… ${detail.props.length - 3} more props types`)
  return lines.join("\n")
}

export function sdkDetailJson(detail: SdkDetail, cwd: string) {
  return {
    package: detail.package,
    version: detail.version,
    name: detail.name,
    specifier: detail.specifier,
    types: displayPath(detail.types, cwd),
    importLine: `import { ${detail.parts.join(", ")} } from "${detail.specifier}"`,
    parts: detail.parts,
    props: detail.props,
  }
}

import { spawnSync } from "node:child_process"
import { existsSync, rmSync, writeFileSync } from "node:fs"
import { join } from "node:path"

import { EnvironmentError } from "./project"

export const ALL_STATES = "all"

const STATE_NAME = /^[A-Za-z0-9][\w-]*$/

// fixtures.ts may export `states`: one entry per named state, each the props the screen gets in it.
const LISTER = [
  'import * as fixtures from "./fixtures"',
  "const states = (fixtures as Record<string, unknown>).states",
  "if (states === undefined) console.log('MOCKUP_STATES none')",
  "else if (typeof states !== 'object' || states === null || Array.isArray(states)) console.log('MOCKUP_STATES invalid')",
  "else {",
  "  const entries = Object.entries(states as Record<string, unknown>)",
  "  const bad = entries.filter(([, props]) => typeof props !== 'object' || props === null || Array.isArray(props))",
  "  console.log('MOCKUP_STATES ' + JSON.stringify({ names: entries.map(([name]) => name), bad: bad.map(([name]) => name) }))",
  "}",
  "",
].join("\n")

export function readStates(mockup: string): string[] | null {
  if (!existsSync(join(mockup, "fixtures.ts")) && !existsSync(join(mockup, "fixtures.tsx"))) return null
  const runner = join(mockup, ".states-check.ts")
  writeFileSync(runner, LISTER)
  let result: ReturnType<typeof spawnSync>
  try {
    result = spawnSync(process.execPath, [".states-check.ts"], { cwd: mockup, encoding: "utf8" })
  } finally {
    rmSync(runner, { force: true })
  }
  const output = `${String(result.stdout ?? "")}${String(result.stderr ?? "")}`
  const line = output.split(/\r?\n/).find((entry) => entry.startsWith("MOCKUP_STATES "))
  if (line === undefined) {
    throw new EnvironmentError(`could not read the states of ${join(mockup, "fixtures.ts")}:\n${output.trim()}`)
  }
  const value = line.slice("MOCKUP_STATES ".length)
  if (value === "none") return null
  if (value === "invalid") {
    throw new EnvironmentError(
      `fixtures.ts exports states that are not an object; export const states = { empty: { … }, loading: { … } }`,
    )
  }
  const parsed = JSON.parse(value) as { names: string[]; bad: string[] }
  if (parsed.bad.length > 0) {
    throw new EnvironmentError(
      `every state in fixtures.ts is the screen's props as an object; not: ${parsed.bad.join(", ")}`,
    )
  }
  const invalid = parsed.names.filter((name) => !STATE_NAME.test(name) || name === ALL_STATES)
  if (invalid.length > 0) {
    throw new EnvironmentError(
      `state names are letters, digits, - and _ (and not "all"), as they name the output file; rename: ${invalid.join(", ")}`,
    )
  }
  return parsed.names
}

// The states one run builds: none without --state (the screen with no props), one, or every one with "all".
export function selectStates(mockup: string, requested: string | undefined): (string | undefined)[] {
  if (requested === undefined) return [undefined]
  const states = readStates(mockup)
  if (states === null || states.length === 0) {
    throw new EnvironmentError(
      `--state ${requested}: fixtures.ts exports no states; export const states = { empty: { … }, loading: { … } }`,
    )
  }
  if (requested === ALL_STATES) return states
  if (!states.includes(requested)) {
    throw new EnvironmentError(`fixtures.ts has no state "${requested}"; it has ${states.join(", ")}`)
  }
  return [requested]
}

export function stateOutName(state: string, theme: string): string {
  return `out-${state}-${theme}.html`
}

import { spawnSync } from "node:child_process"
import { existsSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { dirname, join, resolve } from "node:path"

import { buildMockup, mockupSourceFiles, type BuildOutcome, type BuildSettings, type MockupManifest } from "./build"
import { importRule, partStyleProblems, sdkImportProblems, sourceProblems, type Problem } from "./checks"
import {
  checkTsconfig,
  displayPath,
  EnvironmentError,
  mockupDirectory,
  projectSourceFiles,
  sourceBasenames,
  type MockupProject,
} from "./project"
import { sdkDuplicateWarnings } from "./parts"
import { mockupTsconfigPath } from "./registry"
import { sdkPublicSpecifiers } from "./sdk"

export type ValidateOutcome = {
  build: BuildOutcome
  builds: BuildOutcome[]
  problems: Problem[]
  warnings: string[]
}

const TYPE_ERROR = /^(.+)\((\d+),(\d+)\): error (TS\d+): (.*)$/
const BROWSER_GLOBAL =
  /\b(window|document|navigator|localStorage|sessionStorage|matchMedia|ResizeObserver|IntersectionObserver|MutationObserver)\b/

export function parseTypeErrors(output: string, project: MockupProject, cwd: string): Problem[] {
  const problems: Problem[] = []
  for (const line of output.split(/\r?\n/)) {
    const match = TYPE_ERROR.exec(line)
    if (match !== null) {
      problems.push({
        file: displayPath(resolve(project.root, match[1] ?? ""), cwd),
        line: Number(match[2]),
        column: Number(match[3]),
        rule: "type",
        message: `${match[4] ?? "error"}: ${match[5] ?? ""}`.trimEnd(),
      })
      continue
    }
    const previous = problems.at(-1)
    if (previous !== undefined && /^\s{2}\S/.test(line)) previous.message = `${previous.message} ${line.trim()}`
  }
  return problems
}

function sourceFiles(mockup: string): string[] {
  return mockupSourceFiles(mockup)
}

function typecheck(project: MockupProject, mockup: string): Problem[] {
  const config = existsSync(mockupTsconfigPath(mockup)) ? mockupTsconfigPath(mockup) : checkTsconfig(project.tsconfig)
  const files = sourceFiles(mockup).map((file) => displayPath(file, project.root))
  const result = spawnSync(process.execPath, ["check", "-p", config, "--no-pretty", ...files], {
    cwd: project.root,
    encoding: "utf8",
  })
  if (result.status === 0) return []
  const output = `${result.stdout ?? ""}${result.stderr ?? ""}`
  const problems = parseTypeErrors(output, project, process.cwd())
  if (problems.length === 0) {
    throw new EnvironmentError(`bun check could not read ${displayPath(config, process.cwd())}:\n${output.trim()}`)
  }
  return problems
}

export function renderRunner(mockup: string, state?: string): string {
  const wrapper = existsSync(join(dirname(mockup), "wrapper.tsx"))
  return [
    'import { createElement } from "react"',
    'import { renderToString } from "react-dom/server"',
    'import Screen from "./screen"',
    ...(state === undefined ? [] : ['import { states } from "./fixtures"']),
    ...(wrapper ? ['import Wrapper from "../wrapper"'] : []),
    "try {",
    `  const screen = createElement(Screen, ${state === undefined ? "{}" : `states[${JSON.stringify(state)}]`})`,
    `  const html = renderToString(${wrapper ? "createElement(Wrapper, null, screen)" : "screen"})`,
    '  console.log(html.trim() === "" ? "MOCKUP_RENDER empty" : "MOCKUP_RENDER ok")',
    "} catch (error) {",
    '  console.error("MOCKUP_RENDER error:", error instanceof Error ? error.message : String(error))',
    "  process.exitCode = 1",
    "}",
    "",
  ].join("\n")
}

function firstLine(output: string): string {
  return output.split(/\r?\n/).find((line) => line.trim() !== "") ?? "the server render failed"
}

function smokeRender(
  mockup: string,
  cwd: string,
  state: string | undefined,
): { problems: Problem[]; warnings: string[] } {
  const screen = join(mockup, "screen.tsx")
  const inState = state === undefined ? "" : ` in the ${state} state`
  const located = (rule: string, message: string): Problem[] => [
    { file: displayPath(screen, cwd), line: 1, column: 1, rule, message: `${message}${inState}` },
  ]
  const runner = join(mockup, ".render-check.tsx")
  writeFileSync(runner, renderRunner(mockup, state))
  let result: ReturnType<typeof spawnSync>
  try {
    result = spawnSync(process.execPath, [".render-check.tsx"], {
      cwd: mockup,
      encoding: "utf8",
      env: { ...process.env, NODE_ENV: "production" },
    })
  } finally {
    rmSync(runner, { force: true })
  }
  const output = `${result.stdout ?? ""}${result.stderr ?? ""}`
  if (output.includes("MOCKUP_RENDER ok")) return { problems: [], warnings: [] }
  if (output.includes("MOCKUP_RENDER empty")) {
    const props = state === undefined ? "without props" : `in the ${state} state`
    return { problems: [], warnings: [`${displayPath(screen, cwd)} renders no markup ${props}`] }
  }
  const reported = output
    .split(/\r?\n/)
    .find((line) => line.startsWith("MOCKUP_RENDER error:"))
    ?.replace("MOCKUP_RENDER error:", "")
    .trim()
  const message =
    reported === undefined || reported === "" ? firstLine(output.replaceAll("MOCKUP_RENDER error:", "")) : reported
  if (BROWSER_GLOBAL.test(message)) {
    return { problems: [], warnings: [`the server render needs a browser (${message}); skipped`] }
  }
  return { problems: located("render", message), warnings: [] }
}

// Builds and server-renders each state (one undefined entry: the screen without props); the source rules
// and the type check run once.
export async function validateMockup(
  project: MockupProject,
  settings: BuildSettings,
  states: (string | undefined)[] = [settings.state],
): Promise<ValidateOutcome> {
  const builds: BuildOutcome[] = []
  for (const state of states) {
    // oxlint-disable-next-line no-await-in-loop -- each build writes the same entry file and registry cache
    builds.push(await buildMockup(project, { ...settings, state, out: outFor(settings.out, state, states) }))
  }
  const build = builds[0]
  if (build === undefined) throw new EnvironmentError("validate needs a state to build")
  const mockup = mockupDirectory(project, settings.name)
  const problems: Problem[] = [...dedupe(builds.flatMap((built) => built.problems)), ...build.parts.problems]
  const allowed = importRule([...project.pathPrefixes, "@registry/"], project.dependencies)
  const publicSpecifiers = sdkPublicSpecifiers(project)
  for (const file of sourceFiles(mockup)) {
    const shown = displayPath(file, settings.cwd)
    const source = readFileSync(file, "utf8")
    problems.push(...sourceProblems(shown, source, allowed))
    problems.push(...sdkImportProblems(shown, source, publicSpecifiers))
  }
  for (const file of build.parts.files) {
    problems.push(...partStyleProblems(displayPath(file, settings.cwd), readFileSync(file, "utf8")))
  }
  problems.push(...typecheck(project, mockup))
  const rendered = states.map((state) => smokeRender(mockup, settings.cwd, state))
  problems.push(...rendered.flatMap((render) => render.problems))
  const warnings = [
    ...builds.flatMap((built) => built.warnings),
    ...rendered.flatMap((render) => render.warnings),
    ...sdkDuplicateWarnings(build.parts.sdkParts, sourceBasenames(projectSourceFiles(project))),
  ]
  const sorted = problems.toSorted(
    (left, right) => left.file.localeCompare(right.file) || left.line - right.line || left.column - right.column,
  )
  return { build, builds, problems: sorted, warnings }
}

function dedupe(problems: Problem[]): Problem[] {
  const seen = new Set<string>()
  return problems.filter((problem) => {
    const key = `${problem.file}:${problem.line}:${problem.column}:${problem.rule}:${problem.message}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

// --out with several states names one file per state: its {state} is replaced, and it must have one.
export function outFor(
  out: string | undefined,
  state: string | undefined,
  states: (string | undefined)[],
): string | undefined {
  if (out === undefined || state === undefined) return out
  if (out.includes("{state}")) return out.replaceAll("{state}", state)
  if (states.length > 1) {
    throw new EnvironmentError(`--out needs {state} with --state all, like .mockups/<name>/out-{state}-dark.html`)
  }
  return out
}

export function partsSummary(manifest: MockupManifest): string[] {
  const install =
    manifest.install.length === 0
      ? "install none"
      : `install ${manifest.install.length}: ${manifest.install.map((entry) => entry.item).join(", ")}`
  const proposed =
    manifest.proposed.length === 0
      ? "proposed none"
      : `proposed ${manifest.proposed.length}: ${manifest.proposed
          .map((part) => `${part.name} (${part.props.length} ${part.props.length === 1 ? "prop" : "props"})`)
          .join(", ")}`
  const sdkParts =
    manifest.sdkParts.length === 0
      ? "sdkParts none"
      : `sdkParts ${manifest.sdkParts.length}: ${manifest.sdkParts
          .map((entry) => `${entry.part} ← ${entry.primitive}`)
          .join(", ")}`
  const gaps =
    manifest.gaps.length === 0
      ? "gaps none"
      : `gaps ${manifest.gaps.length}: ${manifest.gaps.map((gap) => `${gap.component} (${gap.missing})`).join(", ")}`
  return [install, proposed, sdkParts, gaps]
}

import { existsSync, readFileSync, readdirSync, realpathSync, statSync } from "node:fs"
import { dirname, join, resolve } from "node:path"

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

function readJson(path: string): unknown {
  try {
    return JSON.parse(readFileSync(path, "utf8"))
  } catch {
    return null
  }
}

function isDirectory(path: string): boolean {
  return existsSync(path) && statSync(path).isDirectory()
}

export function packageRootOf(path: string): string | null {
  let current = isDirectory(path) ? resolve(path) : dirname(resolve(path))
  for (;;) {
    if (existsSync(join(current, "package.json"))) return current
    const parent = dirname(current)
    if (parent === current) return null
    current = parent
  }
}

// The `packages:` list of a pnpm-workspace.yaml, without a YAML parser: one `- glob` per line.
export function pnpmWorkspaceGlobs(text: string): string[] {
  const globs: string[] = []
  let inPackages = false
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/\s+#.*$/, "")
    if (/^packages\s*:/.test(line)) {
      inPackages = true
      const inline = /\[(.*)\]/.exec(line)?.[1]
      if (inline !== undefined) {
        globs.push(...inline.split(",").map((entry) => entry.trim().replaceAll(/^["']|["']$/g, "")))
        inPackages = false
      }
      continue
    }
    if (!inPackages) continue
    if (/^\S/.test(line)) {
      inPackages = false
      continue
    }
    const item = /^\s*-\s*(.+?)\s*$/.exec(line)?.[1]
    if (item !== undefined) globs.push(item.replaceAll(/^["']|["']$/g, ""))
  }
  return globs.filter((glob) => glob !== "")
}

function workspaceGlobs(dir: string): string[] | null {
  const pnpm = join(dir, "pnpm-workspace.yaml")
  if (existsSync(pnpm)) return pnpmWorkspaceGlobs(readFileSync(pnpm, "utf8"))
  const manifest = readJson(join(dir, "package.json"))
  if (!isRecord(manifest)) return null
  const workspaces = manifest["workspaces"]
  if (Array.isArray(workspaces)) return workspaces.filter((entry): entry is string => typeof entry === "string")
  if (isRecord(workspaces) && Array.isArray(workspaces["packages"])) {
    return workspaces["packages"].filter((entry): entry is string => typeof entry === "string")
  }
  return null
}

export type Workspace = { root: string; packages: string[] }

// The nearest folder above `start` that declares workspaces (npm, Yarn and Bun's package.json `workspaces`,
// or pnpm-workspace.yaml), with the folder of every package it lists.
export function findWorkspace(start: string): Workspace | null {
  let current = resolve(start)
  for (;;) {
    const globs = workspaceGlobs(current)
    if (globs !== null) return { root: current, packages: expandGlobs(current, globs) }
    const parent = dirname(current)
    if (parent === current) return null
    current = parent
  }
}

const SKIPPED = new Set(["node_modules", ".git", "dist", "build", ".mockups"])

function expandSegments(base: string, segments: string[], found: Set<string>, depth: number) {
  if (depth > 8) return
  if (segments.length === 0) {
    if (existsSync(join(base, "package.json"))) found.add(base)
    return
  }
  const [segment = "", ...rest] = segments
  if (segment === "**") {
    expandSegments(base, rest, found, depth + 1)
    for (const child of childDirectories(base)) expandSegments(child, segments, found, depth + 1)
    return
  }
  if (!segment.includes("*")) {
    const next = join(base, segment)
    if (isDirectory(next)) expandSegments(next, rest, found, depth + 1)
    return
  }
  const pattern = new RegExp(`^${segment.replaceAll(/[.+?^${}()|[\]\\]/g, "\\$&").replaceAll("*", ".*")}$`)
  for (const child of childDirectories(base)) {
    if (pattern.test(child.slice(base.length + 1))) expandSegments(child, rest, found, depth + 1)
  }
}

function childDirectories(dir: string): string[] {
  if (!isDirectory(dir)) return []
  return readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && !entry.name.startsWith(".") && !SKIPPED.has(entry.name))
    .map((entry) => join(dir, entry.name))
}

export function expandGlobs(root: string, globs: string[]): string[] {
  const found = new Set<string>()
  const excluded = new Set<string>()
  for (const glob of globs) {
    const negated = glob.startsWith("!")
    const segments = glob
      .replace(/^!/, "")
      .replace(/^\.\//, "")
      .split("/")
      .filter((segment) => segment !== "" && segment !== ".")
    expandSegments(root, segments, negated ? excluded : found, 0)
  }
  return [...found].filter((dir) => !excluded.has(dir)).toSorted()
}

function versionParts(version: string): number[] {
  return version.split(/[.-]/).map((part) => Number.parseInt(part, 10))
}

function compareVersions(left: string, right: string): number {
  const [a, b] = [versionParts(left), versionParts(right)]
  for (let index = 0; index < Math.max(a.length, b.length); index += 1) {
    const difference = (a[index] ?? 0) - (b[index] ?? 0)
    if (Number.isNaN(difference)) continue
    if (difference !== 0) return difference
  }
  return 0
}

export type StoreEntry = { dir: string; from: string; version: string }

// A package that only another workspace package depends on, in pnpm's store (node_modules/.pnpm) or Bun's
// isolated one (node_modules/.bun): `<store>/<name with + for />@<version>[_peers|+hash]/node_modules/<name>`.
// `from` is a folder that resolves the package and its own dependencies, the newest version first.
export function storePackages(root: string, name: string): StoreEntry[] {
  const encoded = name.replace("/", "+")
  const found: StoreEntry[] = []
  for (const store of [".pnpm", ".bun"]) {
    const dir = join(root, "node_modules", store)
    if (!isDirectory(dir)) continue
    for (const entry of readdirSync(dir)) {
      if (!entry.startsWith(`${encoded}@`)) continue
      const candidate = join(dir, entry, "node_modules", name)
      if (!existsSync(join(candidate, "package.json"))) continue
      const version = entry.slice(encoded.length + 1).split(/[_+(]/)[0] ?? ""
      found.push({ dir: realpathSync(candidate), from: join(dir, entry), version })
    }
  }
  return found.toSorted((left, right) => compareVersions(right.version, left.version))
}

type MockupBuildLoader = "dataurl"

type MockupBuildResolve = { path: string } | { errors: { message: string }[] } | undefined

type MockupBuildPlugin = {
  name: string
  setup(build: {
    onResolve(
      options: { filter: RegExp },
      callback: (args: { path: string; importer?: string; resolveDir?: string }) => MockupBuildResolve,
    ): void
  }): void
}

type MockupBuildOptions = {
  entrypoints: string[]
  outdir: string
  target: "browser"
  format: "esm"
  minify: boolean
  sourcemap: "external"
  define: Record<string, string>
  loader: Record<string, MockupBuildLoader>
  plugins: MockupBuildPlugin[]
}

type MockupBuildOutput = {
  path: string
  kind: string
  size: number
}

type MockupBuildResult = {
  success: boolean
  outputs: MockupBuildOutput[]
  logs: { level: string; message: string }[]
}

declare const Bun: {
  build(options: MockupBuildOptions): Promise<MockupBuildResult>
  plugin(plugin: MockupBuildPlugin): void
  resolveSync(specifier: string, from: string): string
}
